window.__D("text/torat-shmuel/c061",{"p":[[2001910658,"בחי' ירידה לגבי רבקה, וע\"כ נא' והנערה טובת מראה מאד<sup data-n=\"7886\">41</sup>, פי' מאד הוא בחי' בלי גבול<sup data-n=\"7887\">42</sup>, כי מאד אותיות אדם<sup data-n=\"7888\">43</sup> בהיפך אתווין, אבל לא אדם ממש כי זהו בחי' בלי גבול כו', ע\"כ האמהות מעין דלע\"ל, ע\"כ הי' האבות טפל<sup data-n=\"7889\">44</sup> בנבואה לאמהות.\n<b>עפ\"ז</b><sup data-n=\"7890\">45</sup> יובן מ\"ש משמח חתן וכלה כי עכשיו עיקר החתן כמ\"ש צאינה וראינה בנות ציון בעטרה שעטרה לו אמו<sup data-n=\"7891\">46</sup>, שאמו עטרה לו היינו לחתן את העטרה אבל לא שהיא עצם העטרה, ובברכת אשר ברא נא' משמח חתן עם הכלה שהחתן מקבל מהכלה היינו שקאי על לע\"ל ולע\"ל יהי' נקיבה תסובב גבר<sup data-n=\"7892\">47</sup>, אשת חיל עטרת בעלה<sup data-n=\"7893\">48</sup>, שמל' יהי' בעצמה את<sup data-n=\"7894\">49</sup> העטרה, וע\"כ אנו מסיימים מהרה ישמע<sup data-n=\"7895\">50</sup> כו' קול חתן וקול כלה שעכשיו נא' הקל קול יעקב<sup data-n=\"7896\">51</sup> קול בתראה מלא וא\"ו היינו קול דתורה שהו\"ע המשכה וקול קדמאה חסר וא\"ו היינו קול דתפלה שתפלה הו\"ע העלאה מלמטלמ\"ע צלותא בחשאי<sup data-n=\"7897\">52</sup> קול דלא אשתמע, אבל לע\"ל יהי' קול כלה שתפלה יהי' בקול רם<sup data-n=\"7898\">53</sup>, אשת חיל עטרת בעלה. אך מ\"מ נא' קול חתן ג\"כ מפני שיתגלה קול כלה מפני עצם הגילוי כי שמחה הוא מצד הגילוי<sup data-n=\"7899\">54</sup> ע\"כ כאשר החתן ישיג זאת יהי' ג\"כ קול חתן, מ\"מ עיקר הוא קול כלה וזהו משמח חתן עם הכלה שהחתן מקבל מהכלה.\n<b>וזהו</b> שאמרז\"ל עתידים צדיקים שיאמרו לפניהם קדוש<sup data-n=\"7900\">55</sup> כדרך שיאמרו לפני הקב\"ה, כי הנה ע\"י מעשה המצות מגיעים לבחי' אנשי קדש תהיון לי<sup data-n=\"7901\">56</sup>, שיש קדש וקדוש, פי' קדוש היינו קדש וא\"ו<sup data-n=\"7902\">57</sup>, וא\"ו הוא המשכה וכמו בעטרה שעטרה לו אמו שעטרה הוא בחי' מקיף, כך קדוש הוא מובדל מעולם<sup data-n=\"7903\">58</sup> שהוא בחי' מקיף, ויש",[["7886","41","<b>והנערה טובת מראה מאד</b>: ח\"ש כד, טז."],["7887","42","<b>מאד . . בלי גבול</b>: ראה אגה\"ק סי\"ז. סה\"מ תר\"ם ח\"א ע' תכט. וש\"נ."],["7888","43","<b>מאד אותיות אדם</b>: ראה זהר רע\"מ פינחס רמו, ב. ב\"ר פ\"ח, ה. פ\"ט, יב."],["7889","44","<b>טפל</b>: אוצ\"ל: טפלים."],["7890","45","<b>עפ\"ז</b>: בדרושי חתונה מכ\"ק אדמו\"ר מהר\"ש כאן ע' קעא שנדפס מכת\"י זה: לפ\"ז."],["7891","46","<b>צאינה וראינה . . לו אמו</b>: שה\"ש ג, יא [בדילוג]."],["7892","47","<b>נקיבה תסובב גבר</b>: ירמי' לא, כא."],["7893","48","<b>אשת חיל עטרת בעלה</b>: משלי יב, ד. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370198\" data-slug=\"torah-or\" data-id=\"3901370198\">תו\"א ויגש מג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380155\" data-slug=\"likkutei-torah\" data-id=\"4001380155\">לקו\"ת שמיני יט, ב</a>. ש\"א כ, ב והערה 33."],["7894","49","<b>את</b>: אולי מיותר."],["7895","50","<b>אנו מסיימים מהרה ישמע</b>: בברכת אשר ברא — בדילוג."],["7896","51","<b>הקל קול יעקב</b>: תולדות כז, כב. ראה סידור שער התפלה יט, סע\"א ואילך. (לעיל בחלק המאמרים) מאמר ד\"ה ועבדתם את הוי' אלקיכם ובהערה 115."],["7897","52","<b>צלותא בחשאי</b>: זהר ח\"ש קלב, א. ויגש רי, א. תרומה קלח, ב. ועוד. ראה (לעיל בחלק המאמרים) מאמר ד\"ה וידבר כו' קדושים תהיו ובהערה 69."],["7898","53","<b>שתפלה יהי' בקול רם</b>: ראה תו\"א ויגש מה, ב. לעיל שם ובהערה 78."],["7899","54","<b>שמחה הוא מצד הגילוי</b>: ראה סה\"מ תרל\"א ח\"א ע' קיח."],["7900","55","<b>עתידים צדיקים . . קדוש</b>: ראה ב\"ב עה, ב."],["7901","56","<b>אנשי קדש תהיון לי</b>: משפטים כב, ל [ושם: ואנשי]."],["7902","57","<b>קדש וקדוש . . קדש וא\"ו</b>: ראה זהר אמור צג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380432\" data-slug=\"likkutei-torah\" data-id=\"4001380432\">לקו\"ת בהעלותך ל, סע\"ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380920\" data-slug=\"likkutei-torah\" data-id=\"4001380920\">נצבים נ, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">יו\"כ סט, ב</a> ואילך. שה\"ש כא, ב ואילך. לו, ד. אוה\"ת תזריע כרך ד ע' א'נג."],["7903","58","<b>קדוש הוא מובדל מעולם</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא פמ\"ו (סו, א</a>). (לעיל בחלק המאמרים) מאמר ד\"ה קא מפלגי במתיבתא דרקיע בתחילתו. וש\"נ."]]],[2001910659,"בחי' קדש שהוא קדש מילי' בגרמי'<sup data-n=\"7904\">59</sup>, וע\"י מעהמ\"צ מגיעים לבחי' אנשי קדש תהיון לי, וע\"כ עתידים צדיקים שיאמרו לפניהם קדוש כדרך שיאמרו לפני הקדב\"ה מפני שיגיעו ע\"י מעהמ\"צ לבחי' אנשי קדש כו', וע\"כ והי' ביום ההוא יצאו מים חיים מירושלים אל ים הקדמוני<sup data-n=\"7905\">60</sup>, פי' ים הוא בחי' חכ'<sup data-n=\"7906\">61</sup> וים הקדמוני הוא בחי' חכ' שבכתר<sup data-n=\"7907\">62</sup> וירושלים הוא בחי' כלה ולע\"ל ישפיע ירושלים אל הים הקדמוני. וזהו שארז\"ל מאני של בו\"ד אתה לומד אני של הקב\"ה<sup data-n=\"7908\">63</sup>, פרעה אמר אני פרעה<sup data-n=\"7909\">64</sup> עי\"ז זכה יוסף להיות שולט ומושל על מצרים, כי מצרים הוא מצרים וגבולים<sup data-n=\"7910\">65</sup> שמעלי' ומסתיר, ויוסף הוא שולט על מצרים שלקח כל העלמות<sup data-n=\"7911\">66</sup>, וע\"י שפרעה אמר אני פרעה ונתן את הטבעת ליוסף<sup data-n=\"7912\">67</sup> עי\"ז זכה להיות שולט ומושל על מצרים. וכן מצינו באחשורש שנתן הטבעת למרדכי<sup data-n=\"7913\">68</sup>.\n<b>אך</b> מתחלה צ\"ל בלעו\"ז<sup data-n=\"7914\">69</sup>, כדי שיבואו נש\"י לנקודת פנימי' הלב הי' צ\"ל תחלה בלעו\"ז, ע\"כ נתן אחשורש את הטבעת להמן<sup data-n=\"7915\">70</sup> כדי שעי\"ז יבואו למס\"נ לעורר נקודת יהודית, וכמו שבמ\"ת כתי' ויחן ישראל נגד ההר שנעשו כולם כאיש אחד<sup data-n=\"7916\">71</sup> כך וקבל היהודים לשון יחיד<sup data-n=\"7917\">72</sup> שגמר הקבלה הי' באחשורש שבאו אז למס\"נ ועי\"ז אח\"כ נתן אחשורש את הטבעת למרדכי, כך ע\"י שאמר אני פרעה עי\"ז זכה יוסף להיות שולט ומושל על מצרים, ומזה אתה לומד אני של הקדב\"ה, כאשר יתגלה אני של הקדב\"ה אז יהי' בחי' כלה אשת חיל עטרת. וזהו שבברכה אנו מברכים<sup data-n=\"7918\">73</sup> אני ה', לכאורה מהו\"ע אני ה', האדם כאשר אומר אני יודעים מי הוא, אבל הקדב\"ה כאשר יאמר אני אין אנו יודעים<sup data-n=\"7919\">74</sup> מי הוא שא\"א להשיג אותו ומהו\"ע אני, אלא כמו שלע\"ל יתגלה בחי' אני כך גם עכשיו יש ג\"כ בחי' אני במצות. וזהו מאני של בו\"ד ע\"י שפרעה",[["7904","59","<b>קדש מילי' בגרמי'</b>: זהר אמור צד, ב."],["7905","60","<b>והי' ביום ההוא . . ים הקדמוני</b>: זכרי' יד, ח [בדילוג. ושם: הים]."],["7906","61","<b>ים הוא בחי' חכ'</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה זכור את יום השבת הערה 167."],["7907","62","<b>וים הקדמוני . . חכ' שבכתר</b>: ראה אוה\"ת ואתחנן ע' רמח וע' רעו. (לעיל בחלק המאמרים) מאמר ד\"ה וידבר כו' קדושים תהיו על יד הערה *91."],["7908","63","<b>מאני של בו\"ד . . הקב\"ה</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה זכור את יום השבת רפ\"ה. וש\"נ."],["7909","64","<b>אני פרעה</b>: מקץ מא, מד."],["7910","65","<b>מצרים הוא מצרים וגבולים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370287\" data-slug=\"torah-or\" data-id=\"3901370287\">תו\"א בשלח סד, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">סע\"ג. יתרו סז, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370318\" data-slug=\"torah-or\" data-id=\"3901370318\">עא, ג</a>."],["7911","66","<b>שלקח כל העלמות</b>: בדרושי חתונה מכ\"ק אדמו\"ר מהר\"ש כאן ע' קעב שנדפס מכת\"י זה: שלקח כל העליות. לקמן בהנחה שלאח\"ז: דהיינו בכל המצרים וגבולים הי' יוסף מושל ושולט עליהם."],["7912","67","<b>ונתן את הטבעת ליוסף</b>: מקץ מא, מב."],["7913","68","<b>באחשורש שנתן הטבעת למרדכי</b>: אסתר ח, ב."],["7914","69","<b>בלעו\"ז</b>: ראה קהלת ז, יד. סה\"מ תרל\"ח ע' קלד."],["7915","70","<b>נתן אחשורש את הטבעת להמן</b>: אסתר ג, י."],["7916","71","<b>ויחן ישראל . . כאיש אחד</b>: ראה יתרו יט, ב (בדילוג] וברש\"י שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211104\" data-slug=\"likkutei-sichot\" data-id=\"1300211104\">לקו\"ש יתרו כרך כא ע' 104</a>."],["7917","72","<b>וקבל היהודים לשון יחיד</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370437\" data-slug=\"torah-or\" data-id=\"3901370437\">תו\"א מג\"א צז, סע\"ד</a> ואילך."],["7918","73","<b>שבברכה אנו מברכים</b>: לקמן בהנחה שלאח\"ז: מה שמסיים בכל המצות."],["7919","74","<b>אני ה' . . אין אנו יודעים</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ועבדתם את הוי' אלקיכם ובהערה 19."]]],[2001910660,"אמר אני פרעה ונתן הטבעת ליוסף ועל הטבעת הי' חותם<sup data-n=\"7920\">75</sup> שזהו\"ע גושפנקא דחתים בי' מלכא שחתים בי' שמיא וארעא<sup data-n=\"7921\">76</sup> עי\"ז זכה יוסף להיות שולט ומושל על מצרים, כך כאשר יתגלה לע\"ל בחי' אני עי\"ז יהי' בחי' כלה אשת חיל עטרת בעלה כו'.\n<b>וזהו</b> מ\"ש רני עקרה לא ילדה פי' לא ילדה הנה כתי' בכל צרתם לא צר<sup data-n=\"7922\">77</sup> שיש קרי וכתיב, והקרי הוא בוא\"ו והכתיב הוא לא באלף, והם רחוקים זמ\"ז, שלא באלף פי' אין, ולו בוא\"ו פי' הן, ובאמת מנושא הכתוב משמע שלא<sup data-n=\"7923\">78</sup> צר היינו שנוגע לו, מפני שאח\"כ דכתי'<sup data-n=\"7924\">79</sup> ומלאך פניו<sup data-n=\"7925\">80</sup> הושיעם באהבתו משמע שנוגע לו ח\"ו כו'. אך הענין הוא הנה כי הוא עשנו ולא אנחנו עמו<sup data-n=\"7926\">81</sup> שיש ג\"כ קרי וכתיב, וכן אל דעות ה' ולא נתכנו עלילות<sup data-n=\"7927\">82</sup> שיש ג\"כ קרי וכתיב, הנה מצד לא באלף שם אינו נוגע כי שם אם צדקת מה תתן לו<sup data-n=\"7928\">83</sup> כו', כחשיכה כאורה<sup data-n=\"7929\">84</sup>, שלא די שחושך שוה לאור אלא שגם האור שוה לחושך ע\"כ שם אינו נוגע, אבל לו בוא\"ו שם נוגע כו'. אבל באמת הנה הוא\"ו הוא איתא בזוהר ונתתם לו אות אמת<sup data-n=\"7930\">85</sup> דא אות וא\"ו<sup data-n=\"7931\">86</sup> שהוא בריח התיכון שמבריח<sup data-n=\"7932\">87</sup> מן הקצה אל הקצה, א\"כ כיון שמבריח מן קצה העליון עד קצה התחתון א\"כ קצה התחתון מגיע לקצה העליון, א\"כ גם באלף מגיע לשם, כי באמת גם לאלף נוגע כמבואר בזוהר להתם מטי' עקתא דישראל<sup data-n=\"7933\">88</sup>, א\"כ גם לא באלף גם שם נוגע האתעדל\"ת, וזהו לא ילדה שגם מלא באלף יהי' בבחי' לידה וגילוי. כי הנה כתי' ושרי אשת אברם לא ילדה לו<sup data-n=\"7934\">89</sup>, הנה שם לא ילדה, אך הנה כתי' ותהי שרי עקרה<sup data-n=\"7935\">90</sup> אין לה ולד וארז\"ל כל מקום שנא' אין לה והוה לה<sup data-n=\"7936\">91</sup>, ולשרי אין לה ולד<sup data-n=\"7937\">92</sup> והוה לה,",[["7920","75","<b>ועל הטבעת הי' חותם</b>: ראה רמב\"ן מקץ מא, מב."],["7921","76","<b>גושפנקא . . שמיא וארעא</b>: ראה עמה\"מ ש\"ו שער עולם התוהו ספ\"ד טו, ג בשם הזהר."],["7922","77","<b>בכל צרתם לא צר</b>: ישעי' סג, ט. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תש ובהנסמן במ\"מ לשם. שה\"א ב, ב ובהערה 17. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540089\" data-slug=\"torat-chaim\" data-id=\"2300540089\">תו\"ח וארא ח\"א נא, ד</a>."],["7923","78","<b>שלא</b>: בדרושי חתונה מכ\"ק אדמו\"ר מהר\"ש כאן ע' קעב שנדפס מכת\"י זה: שלו."],["7924","79","<b>מפני שאח\"כ דכתיב</b>: מתחילה כתב: מפני דכתיב. ואח\"כ הוסיף תיבת: שאח\"כ בין השיטין. וכנראה ששכח למחוק אות ד' מתיבת: דכתיב."],["7925","80","<b>פניו</b>: בדרושי חתונה מכ\"ק אדמו\"ר מהר\"ש כאן ע' קעב שנדפס מכת\"י זה: הוי'!"],["7926","81","<b>כי הוא עשנו ולא אנחנו עמו</b>: תהלים ק, ג [בדילוג]. ראה מאמרי אדה\"א דברים ח\"ג ע' תתיג. ח\"ד ע' א'קע. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670467\" data-slug=\"torat-chaim\" data-id=\"2300670467\">תו\"ח לך פח, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550513\" data-slug=\"torat-chaim\" data-id=\"2300550513\">יתרו ח\"ב רסב, א</a>."],["7927","82","<b>אל דעות ה' ולא נתכנו עלילות</b>: שמו\"א ב, ד. ראה מאמרי אדה\"א נ\"ך ע' תרא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670476\" data-slug=\"torat-chaim\" data-id=\"2300670476\">תו\"ח לך פח, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680378\" data-slug=\"torat-chaim\" data-id=\"2300680378\">תולדות קנה, ד</a>. יתרו שם."],["7928","83","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["7929","84","<b>כחשיכה כאורה</b>: תהלים קלט, יב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380124\" data-slug=\"likkutei-torah\" data-id=\"4001380124\">לקו\"ת צו יב, א</a>. סה\"מ תר\"ם ח\"א ע' שו. וש\"נ."],["7930","85","<b>ונתתם לו אות אמת</b>: יהושע ב, יב [ושם: לי]."],["7931","86","<b>דא אות וא\"ו</b>: ראה זהר ויקרא ב, א. ויחי רמא, ב. מאמרי אדה\"ז תקס\"ה ח\"א ע' שסח ואילך. מאמרי אדה\"א הנחות תקע\"ז ע' ח ואילך. ביאוה\"ז להצ\"צ ויקרא כרך א ע' שיג ואילך."],["7932","87","<b>בריח התיכון שמבריח</b>: ע\"פ תרומה כו, כח. ויקהל לו,לג."],["7933","88","<b>להתם מטי' עקתא דישראל</b>: ראה זהר וירא קכ, ב."],["7934","89","<b>ושרי אשת אברם לא ילדה לו</b>: לך טז, א."],["7935","90","<b>ותהי שרי עקרה</b>: נח יא, ל."],["7936","91","<b>כל מקום שנאמר אין לה והוה לה</b>: ראה ב\"ר ספל\"ח. (לעיל בחלק המאמרים) מאמר ד\"ה והנה תורה היא בחי' קו האמצעי ובהערה 216."],["7937","92","<b>ולשרי אין לה ולד</b>: אולי הכוונה לסיום הכתוב דלעיל ותהי שרי עקרה."]]],[2001910661,"ולציון דורש אין לה<sup data-n=\"7938\">93</sup> והוה לה, ולחנה אין לה ולד<sup data-n=\"7939\">94</sup> והוה לה, כמ\"ש כי אין מחסור ליריאיו<sup data-n=\"7940\">95</sup> פי' אין אותיות אין ומאין ממלא החסרון ע\"כ מאין עי\"ז והוה לה, כך רני עקרה לא ילדה שע\"י לא שהעדר הגילוי מלא נעשה לידה וגילוי כו'.\n<b>וזהו</b> שוש תשיש ותגל העקרה פי' תשיש היינו כמ\"ש ישמח ה' במעשיו ישמח ישראל בעושיו<sup data-n=\"7942\">97</sup> וארז\"ל שמח לא נא'<sup data-n=\"7941\">96</sup> אלא ישמח עתיד הקב\"ה לשמוח כו', הקב\"ה היינו סדר השתלשלות קדוש וברוך<sup data-n=\"7943\">98</sup> ועתיד לשמוח שיומשך מלמעלה מסדר השתל' בסדר השתל', כי לע\"ל כאשר יתגלה הטעם ממילא יהי' הרצון ג\"כ באופן אחר. ותגל העקרה בקבוץ בני' היינו כמ\"ש ברחמי' גדולים אקבצך היינו רחמים כי יש רחמן ורחמים<sup data-n=\"7944\">99</sup>, פי' רחמן היינו רחמים שבסדר השתלשל' חסד דין רחמים הגם שיש רחמים אבל יש מנגד לזה חסד ודין<sup data-n=\"7945\">100</sup>, אבל רחמים היינו שלמעלה מסדר השתלשלות עי\"ז בקבוץ בני' כו'. א\"כ עפי\"ז יובן שאבודרהם פי' ששוש תשיש קאי על שמחת ירושלים כי זה קאי על לע\"ל, אך כדי לבוא לזה צ\"ל תחלה משמח חתן וכלה, שחתן הוא משפיע בעטרה שעטרה לו אמו שאמו עטרה לו עטרה, ואח\"כ אפשר לבוא למשמח חתן עם הכלה שעיקר הכלה כמו שיהי' לע\"ל אשת חיל עטרת בעלה, כמשוש חתן על כלה ישיש כו', וזהו שוש תשיש כו'.",[["7938","93","<b>ולציון דורש אין לה</b>: ירמי' ל, יז [ושם: ציון היא. ראה גם לעיל שם ובהערה 223]."],["7939","94","<b>ולחנה אין לה ולד</b>: שמו\"א א, ב [ושם: ולחנה אין ילדים. ראה גם לעיל שם ובהערה 222]."],["7940","95","<b>כי אין מחסור ליריאיו</b>: תהלים לד, י. ראה גם לעיל שם ובהערה 235."],["7942","97","<b>ישמח ישראל בעושיו</b>: תהלים קמט, ב."],["7941","96","<b>ישמח ה' . . שמח לא נא'</b>: תהלים קד, לא. ראה ויק\"ר פ\"כ, ב. לקו\"ת שמע\"צ פט, א ואילך. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650264\" data-slug=\"or-hatorah-hb\" data-id=\"8316650264\">אוה\"ת שבועות ע' קלד</a> ואילך — נדפס גם באוה\"ת תהלים כרך ב ע' תתקצג."],["7943","98","<b>הקב\"ה . . קדוש וברוך</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה קא מפלגי במתיבתא דרקיע בתחילתו. וש\"נ."],["7944","99","<b>רחמן ורחמים</b>: ראה לקמן בהנחה שלאח\"ז."],["7945","100","<b>רחמים . . מנגד לזה חסד ודין</b>: ראה לקמן בהנחה שלאח\"ז: שכנגד החסד והרחמים יש מדה\"ד."]]],[2001910662,"<h3>שוש תשיש</h3>\n<b>בס\"ד</b>\n<b>שוש</b> תשיש<sup data-n=\"7946\">1</sup> ותגל העקרה בקיבוץ בניה לתוכה בשמחה<sup data-n=\"7947\">2</sup>, הנה איתא באבודרהם שברכה זו<sup data-n=\"7948\">3</sup> נתקנה כנגד שמחת ירושלים העתידה שנמשלה לחתן וכלה כו' משום שנאמר אם לא אעלה את ירושלים על ראש שמחתי<sup data-n=\"7949\">4</sup>, ומפרש שברכה זו נק' ראש השמחה כי הברכה שלאחריה שמח תשמח היא עיקר כנגד שמחת חתן וכלה,",[["7946","1","<b>שוש תשיש</b>: הנחה זו נעתקה מבוך 1075 ע' 184. הנחה אחרת נדפסה לפנ\"ז."],["7947","2","<b>שוש תשיש . . לתוכה בשמחה</b>: נוסח ברכת נשואין."],["7948","3","<b>איתא באבודרהם שברכה זו</b>: ראה גם בהנחה שלפנ\"ז. וש\"נ."],["7949","4","<b>אם לא אעלה . . ראש שמחתי</b>: תהלים קלז, ו."]]],[2001910663,"ותגל עקרה<sup data-n=\"7950\">5</sup> ע\"ש רני עקרה<sup data-n=\"7951\">6</sup>, בקיבוץ בניה ע\"ש מ\"ש ברני עקרה וברחמים גדולים אקבצך<sup data-n=\"7952\">7</sup>, והנה לשון תשיש הוא שמשמח אחרים<sup data-n=\"7953\">8</sup> כמ\"ש ישיש עליך אלקיך<sup data-n=\"7954\">9</sup> וכמו שאומרים בברכה שניה<sup data-n=\"7955\">10</sup> משמח חתן עם הכלה<sup data-n=\"7956\">11</sup> שעיקר השמחה שייך להכלה והכלה משמח את החתן ג\"כ, וצריך להבין מהו ענין שייכות ברכה זו לשמחת ירושלים, ולהבין זה צ\"ל השינוי שבברכת שמח תשמח מסיים משמח חתן וכלה ומשמע מזה שעיקר השמחה הוא של החתן ומחמתו תשמח גם הכלה וכ\"מ בגמ' שעיקר השמחה הוא של חתן כמאמרם ז\"ל כל הנהנה מסעודת חתן<sup data-n=\"7958\">13</sup> ואינו משמחו כו' ואם משמחו מה שכרו כו', ובברכת אשר ברא מסיימים משמח חתן עם הכלה<sup data-n=\"7957\">12</sup> משמע שעיקר השמחה הוא של הכלה ומחמתה ישמח גם החתן, ולכאורה ה\"ז שני הפכים, וגם צ\"ל מ\"ש רני עקרה לא ילדה מהו השמחה אם לא ילדה, ומ\"ש עד עקרה ילדה שבעה<sup data-n=\"7959\">14</sup> שם הוא השמחה מהלידה אבל ממה שלא ילדה מהו השמחה.\n<b>והענין</b> דהנה ברכת שמח תשמח הוא כנגד סדר הגילויים של עכשיו, וברכת אשר ברא<sup data-n=\"7960\">15</sup> הוא כנגד הגילוים דלע\"ל, והנה שרש ההפרש בין הגילוים דעכשיו ודלע\"ל כי הנה התורה דעכשיו נק' בשם אירוסין<sup data-n=\"7961\">16</sup> וכמ\"ש וארשתיך לי<sup data-n=\"7962\">17</sup> כו' וכמ\"ש במ\"ת וקדשתם היום<sup data-n=\"7963\">18</sup> כו' שנק' בשם קדושין ולכן החתן אומר הרי את מקודשת והכלה שותקת<sup data-n=\"7964\">19</sup> שהחתן אינו נותן לה כ\"א טבעת קדושין<sup data-n=\"7965\">20</sup> שהוא רק מקיף<sup data-n=\"7966\">21</sup> ולכן אנו מברכים על המצות אשר קדשנו כו', ומה שאנו מבקשים קדשנו במצותיך<sup data-n=\"7967\">22</sup> היינו שיהי' עכשיו הגילוי מהמצות שלמעלה שיתגלו לע\"ל וכמ\"ש ושם נעשה לפניך כמצות רצונך<sup data-n=\"7968\">23</sup> והבקשה הוא שיאיר ויתגלה הארה מהם עכשיו, אבל",[["7950","5","<b>עקרה</b>: כ\"ה גם באבודרהם."],["7951","6","<b>רני עקרה</b>: ישעי' נד, א."],["7952","7","<b>וברחמים גדולים אקבצך</b>: ישעי' שם, ז."],["7953","8","<b>לשון תשיש הוא שמשמח אחרים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380160\" data-slug=\"likkutei-torah\" data-id=\"4001380160\">לקו\"ת תזריע כ, א</a>. סה\"מ תר\"ם ח\"ב ע' תרח ובהערה 6."],["7954","9","<b>ישיש עליך אלקיך</b>: ישעי' סב, ה."],["7955","10","<b>בברכה שניה</b>: הכוונה לברכה שלאחר זו, ברכת אשר ברא."],["7956","11","<b>משמח חתן עם הכלה</b>: ראה גם בסמוך בפנים."],["7958","13","<b>כל הנהנה מסעודת חתן</b>: ברכות ו, ב."],["7957","12","<b>משמח חתן וכלה . . חתן עם הכלה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370202\" data-slug=\"torah-or\" data-id=\"3901370202\">תו\"א ויגש מד, ד</a>. דרושי חתונה מכ\"ק אדמו\"ר מהר\"ש ע' סט. שם ע' קסז. נדפס גם בסה\"מ תרל\"ב ח\"ב ע' תקמ."],["7959","14","<b>עד עקרה ילדה שבעה</b>: שמו\"א ב, ה."],["7960","15","<b>ברכת שמח תשמח . . אשר ברא</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370203\" data-slug=\"torah-or\" data-id=\"3901370203\">תו\"א ויגש מד. ד. מה, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380112\" data-slug=\"likkutei-torah\" data-id=\"4001380112\">לקו\"ת צו ט, סע\"א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381321\" data-slug=\"likkutei-torah\" data-id=\"4001381321\">שה\"ש מח, ב</a>. דרושי חתונה מכ\"ק אדמו\"ר מהר\"ש ע' סט. וש\"נ."],["7961","16","<b>התורה דעכשיו נק' בשם אירוסין</b>: ראה גם בהנחה שלפנ\"ז ובהערה 16."],["7962","17","<b>וארשתיך לי</b>: הושע ב, כא-כב."],["7963","18","<b>וקדשתם היום</b>: יתרו יט, י."],["7964","19","<b>הרי את מקודשת והכלה שותקת</b>: נוסח הקדושין. ראה קדושין ה, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540923\" data-slug=\"torat-chaim\" data-id=\"2300540923\">תו\"ח בא ח\"א קי, א</a> ובהנסמן שם."],["7965","20","<b>טבעת קדושין</b>: ראה רמ\"א בשו\"ע אבהע\"ז רסכ\"ז. סל\"א, ס\"ב."],["7966","21","<b>טבעת קדושין שהוא רק מקיף</b>: ראה סידור ברכת נשואין קלח, ד. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370202\" data-slug=\"torah-or\" data-id=\"3901370202\">תו\"א ויגש מד, ד</a>. הנסמן בסה\"מ תרל\"ח ע' קנח הערה 1035."],["7967","22","<b>קדשנו במצותיך</b>: תפלת העמידה לשבת ויו\"ט. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה אז ישיר משה פ\"ד. וש\"נ."],["7968","23","<b>ושם נעשה לפניך כמצות רצונך</b>: מוסף ליו\"ט [בדילוג]. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה קדש ישראל לה' פ\"א. וש\"נ."]]],[2001910664,"לע\"ל יהי' נשואין<sup data-n=\"7969\">24</sup> וכמ\"ש ביום ההוא תקראו לי אישי<sup data-n=\"7970\">25</sup>, וכתי' כי בועליך עושייך<sup data-n=\"7971\">26</sup> כו' שלע\"ל יהי' גילוי פנימי' התורה.\n<b>ולהבין</b> ההפרש בין התורה שנק' ארוסין ובין נשואין, הנה אי' בזהר שיש שני בחי' מוחא וגלגלתא דחפיא על מוחא<sup data-n=\"7972\">27</sup>, והנה הגלגלתא מכסה על הטעם והמוחין כי גלגלתא נק' רצון<sup data-n=\"7973\">28</sup>, והנה המצות של עכשיו הוא רק רצה\"ע אבל הטעם מהמצוה לא נתגלה, וכמו למשל אדם שאומר לחבירו שהוא רוצה שיעשה כך ואינו אומר לו הטעם למה הוא רוצה כך הרי ע\"כ שיש לו טעם אלא שאינו רוצה לגלות הטעם אלא שהוא כמוס לבעל הרצון, וכן יובן במצות דהנה ע\"י כל מצוה נמשך המשכה עליונה כמו ע\"י ד' בתים דתפילין נמשך ד' מוחין<sup data-n=\"7974\">29</sup> עליונים, ע\"י פ' קדש נמשך חכ\"ע, והי' כי יביאך בינה, שמע והי' א\"ש דעת הנחלק לחו\"ג<sup data-n=\"7975\">30</sup>, הרי אינו מובן כלל ע\"פ שכל אנושי האיך ע\"י קלף גשמי ודיו גשמי יומשך מוחין עליונים אלא שהוא כמוס הטעם עמדי כי טעמי המצות לא נתגלו<sup data-n=\"7976\">31</sup>, אבל לע\"ל יתגלה פנימי' התורה טעמי תו' הרצון והטעם והעונג הנעלם שיש בהמצוה<sup data-n=\"7977\">32</sup>, ולכן נק' נשואין שהוא גילוי פנימי'. וזהו עצמו ההפרש בין ב' הברכות, דברכת חתן וכלה קאי על גילויים דעכשיו, ועכשיו עיקר השמחה הוא של החתן וכמ\"ש צאינה וראינה כו' בעטרה שעטרה לו אמו<sup data-n=\"7978\">33</sup> שהאם עוטר העטרה להחתן, ומפני שעכשיו ההעטרה הוא לו דוקא מפני זה הוא שמחתו דוקא, אך מ\"מ כעת האם עוטר לו העטרה אבל לא שהוא עצמו<sup data-n=\"7979\">34</sup> העטרה, אבל לע\"ל כתי' א\"ח עט\"ב שהכלה בעצמה היא תהי' העטרה, וכמ\"ש נקבה תסובב גבר<sup data-n=\"7980\">35</sup>, ולכן כתי' משמח חתן עם הכלה שעיקר השמחה הוא של הכלה והחתן יקבל ממנה השמחה.",[["7969","24","<b>לע\"ל יהי' נשואין</b>: ראה גם בהנחה שלפנ\"ז ובהערה 16."],["7970","25","<b>ביום ההוא תקראו לי אישי</b>: ראה גם בהנחה שלפנ\"ז ובהערה 22."],["7971","26","<b>כי בועליך עושייך</b>: ישעי' נד, ה."],["7972","27","<b>וגלגלתא דחפיא על מוחא</b>: ראה זהר אד\"ר נשא קכח, ב."],["7973","28","<b>גלגלתא נק' רצון</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380505\" data-slug=\"likkutei-torah\" data-id=\"4001380505\">לקו\"ת שלח מח, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380936\" data-slug=\"likkutei-torah\" data-id=\"4001380936\">ר\"ה נד, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540414\" data-slug=\"torat-chaim\" data-id=\"2300540414\">תו\"ח בא ח\"א צ, א</a>."],["7974","29","<b>ד' בתים דתפילין נמשך ד' מוחין</b>: ראה זהר ואתחנן רסב, א. פע\"ח שער התפילין שער ד, פ\"א ואילך. סידור שער התפילין ז, א. אמרי בינה שער התפילין קיב, א ואילך. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ד ע' א'רמא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670598\" data-slug=\"torat-chaim\" data-id=\"2300670598\">תו\"ח נח עח, ד</a> הערה 34."],["7975","30","<b>דעת הנחלק לחו\"ג</b>: ראה סידור שם. ש\"א פו, ב הערה 43."],["7976","31","<b>טעמי המצות לא נתגלו</b>: ראה סנהדרין כא, ב. אגה\"ק סי\"ט (ע' קכח) ובמ\"מ הגהות והע\"ק לשם. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370128\" data-slug=\"torah-or\" data-id=\"3901370128\">תו\"א ח\"ש יז, ב</a>. וישב כז, ב. סה\"מ תרכ\"ט ס\"ע רנב ואילך. וש\"נ. תרל\"ח ע' תמו. סה\"מ מלוקט ב' ע' כ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141118\" data-slug=\"likkutei-sichot\" data-id=\"1300141118\">לקו\"ש תבוא כרך יד ע' 106</a> הערה 33."],["7977","32","<b>לע\"ל . . טעמי תו' . . שיש בהמצוה</b>: ראה רש\"י שה\"ש א, ב [ולהעיר ממ\"מ הגהות והע\"ק לאגה\"ק שם]. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תקצ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550664\" data-slug=\"torat-chaim\" data-id=\"2300550664\">תו\"ח תצוה ח\"ב שנד, ג</a>. וש\"נ."],["7978","33","<b>צאינה וראינה . . לו אמו</b>: שה\"ש ג, יא."],["7979","34","<b>שהוא עצמו</b>: אוצ\"ל: שהיא עצמה."],["7980","35","<b>א\"ח עט\"ב . . נקבה תסובב גבר</b>: משלי יב, ד. ירמי' לא, כא."]]],[2001910665,"<b>ובזה</b> יובן מארז\"ל עתידים צדיקים שיאמרו לפניהם קדוש<sup data-n=\"7981\">36</sup>, כי הנה יש ב' בחי' קדוש וקדש<sup data-n=\"7982\">37</sup>, קדוש הוא הגילוי של עכשיו שהו\"ע העטרה, כי קדוש פי' מובדל<sup data-n=\"7983\">38</sup> שאינו מאיר בפנימי' וה\"ז רק כמו עטרה שהוא רק בחי' מקיף, אבל יש בחי' קדש שהוא מובדל לגמרי גם מהיות בחי' מקיף, ולע\"ל כאשר יתעלו נש\"י לקדש עליון וכמ\"ש ואנשי קדש תהיון לי<sup data-n=\"7984\">39</sup> והרי ע\"י קיום מעשה המצות דעכשיו שהם בבחי' קדוש הרי יהי' הם בעצמם בבחי' קדש ולכן יאמרו לפניהם קדוש. וזהו מ\"ש והי' ביום ההוא יצאו מים חיים מירושלים חצים אל הים הקדמוני<sup data-n=\"7985\">40</sup>, ירושלים הוא כנס\"י<sup data-n=\"7986\">41</sup> כלה, ולע\"ל מפני שהם עצמם יהי' העטרה לכן יהי' משפיעים לים שהוא ח\"ע<sup data-n=\"7987\">42</sup> וגם לים הקדמוני שהוא חכ' שבכתר<sup data-n=\"7988\">43</sup>. ולכן בברכה זו<sup data-n=\"7989\">44</sup> כתי' מהרה ישמע כו' קול חתן וקול כלה, כי עכשיו החתן אומר הרי את כו' והכלה שותקת כי הכלה אין לה עכשיו קול, דהנה כתי' הקל קול יעקב<sup data-n=\"7990\">45</sup> קלא קדמאה חסר וא\"ו שהוא קול דתפלה שעכשיו צלותא בחשאי<sup data-n=\"7991\">46</sup> כי תפלה שהוא בחי' כלה הוא העלאה מלמטה למעלה והתורה שהוא בחי' חתן יש לו קול כי לימוד התורה צ\"ל בקול, אבל לע\"ל יהי' קול כלה שאז יהי' צלותא בקול רם<sup data-n=\"7992\">47</sup>, ע\"ד מ\"ש עכשיו והאלקים יעננו בקול<sup data-n=\"7993\">48</sup> בקול רם, כמ\"כ יהי' תפלה לע\"ל בקול רם, ומ\"מ יהי' אז ג\"כ קול לחתן מפני עוצם הגילוי דמדריגת כלה שהשמחה הוא מחמת הגילוי והחתן ישיג ויקבל ממדריגה זו לכן יהי' לו אז ג\"כ קול, ולכן מצינו בג' אבות שהטעימן מעין עוה\"ב<sup data-n=\"7994\">49</sup> דכתי' בהם בכל מכל כל<sup data-n=\"7995\">50</sup>, היו הם טפלים להאמהות בנביאות, באברהם כתיב כל אשר תאמר אליך שרה שמע בקולה<sup data-n=\"7996\">51</sup>, והגם שאברהם הי' משפיע לשרה כ\"ז הוא עכשיו בגילוי שע\"פ סדר השתל' אבל לע\"ל כאשר יהי' גילוי שלמעלה מסדר השתל' שרה היא",[["7981","36","<b>עתידים צדיקים . . קדוש</b>: ראה ב\"ב עה, ב."],["7982","37","<b>קדוש וקדש</b>: ראה זהר אמור צג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380432\" data-slug=\"likkutei-torah\" data-id=\"4001380432\">לקו\"ת בהעלותך ל, סע\"ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380920\" data-slug=\"likkutei-torah\" data-id=\"4001380920\">נצבים נ, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">יו\"כ סט, ב</a> ואילך. שה\"ש כא, ב ואילך. לו, ד. אוה\"ת תזריע כרך ד ע' א'נג."],["7983","38","<b>קדוש פי' מובדל</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא פמ\"ו (סו, א</a>). (לעיל בחלק המאמרים) מאמר ד\"ה קא מפלגי במתיבתא דרקיעא בתחילתו. וש\"נ."],["7984","39","<b>ואנשי קדש תהיון לי</b>: משפטים כב, ל."],["7985","40","<b>והי' ביום ההוא . . הים הקדמוני</b>: זכרי' יד, ח."],["7986","41","<b>ירושלים הוא כנס\"י</b>: ראה אוה\"ת ואתחנן ע' רמח וע' רעו."],["7987","42","<b>לים שהוא ח\"ע</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה זכור את יום השבת הערה 167."],["7988","43","<b>לים הקדמוני שהוא חכ' שבכתר</b>: ראה אוה\"ת ואתחנן שם. (לעיל בחלק המאמרים) מאמר ד\"ה וידבר כו' קדושים תהיו על יד הערה *91."],["7989","44","<b>בברכה זו</b>: אשר ברא."],["7990","45","<b>הקל קול יעקב</b>: תולדות כז, כב. ראה סידור שער התפלה יט, סע\"א ואילך. (לעיל בחלק המאמרים) מאמר ד\"ה ועבדתם את הוי' אלקיכם ובהערה 115."],["7991","46","<b>צלותא בחשאי</b>: זהר ח\"ש קלב, א. ויגש רי, א. תרומה קלח, ב. ועוד. ראה (לעיל בחלק המאמרים) מאמר ד\"ה וידבר כו' קדושים תהיו ובהערה 69."],["7992","47","<b>לע\"ל . . צלותא בקול רם</b>: ראה תו\"א ויגש מה, ב. לעיל שם ובהערה 78."],["7993","48","<b>והאלקים יעננו בקול</b>: יתרו יט, יט. ראה רש\"י ורשב\"ם שם."],["7994","49","<b>בג' אבות שהטעימן מעין עוה\"ב</b>: ב\"ב טז, סע\"ב ואילך. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה וידבר כו' קדושים תהיו פ\"ב פיסקא ושרש הענין. וש\"נ."],["7995","50","<b>בכל מכל כל</b>: ח\"ש כד, א. תולדות כז, לג. וישלח לג, יא."],["7996","51","<b>כל אשר תאמר. . בקולה</b>: וירא כא, יב. מדרש אגדה ורש\"י שם."]]],[2001910666,"מקור המשפיע, וכן ברבקה הגם שרבקה<sup data-n=\"7997\">52</sup> הוא שם ב\"ן<sup data-n=\"7998\">53</sup> ויצחק הוא שם מ\"ה<sup data-n=\"7999\">54</sup> ומ\"ה מברר ב\"ן<sup data-n=\"8000\">55</sup> מ\"מ טפל הוא לרבקה מפני שב\"ן לאחר הבירור הוא למעלה מעלה משם מ\"ה<sup data-n=\"8001\">56</sup>, ולכן כתי' ברבקה והנערה טובת מראה מאד<sup data-n=\"8002\">57</sup> ומאד הוא בל\"ג<sup data-n=\"8003\">58</sup> שלכן כתי' בה ותרד העיינה ותמלא כדה<sup data-n=\"8004\">59</sup> שכללות התו' דעכשיו שהוא כד מן הים הוא ירידה לגבי מדריגתה כי ב\"ן לאחר הבירור יהי' בבחי' מאד בל\"ג, אשר אדם הוא אותיות מאד<sup data-n=\"8005\">60</sup> ולא מאד בעצם.\n<b>והנה</b> כל הגילוים דלע\"ל יהי' ע\"י קיום התומ\"צ דעכשיו שהם בבחי' ארוסין. והענין דהנה ארז\"ל מאני של בו\"ד אתה למד אני של הקב\"ה<sup data-n=\"8006\">61</sup>, דמה פרעה שאמר ליוסף אני פרעה<sup data-n=\"8007\">62</sup> זכה יוסף לכל הגדולה הזה שהי' שולט ומושל על כל ארץ מצרים<sup data-n=\"8008\">63</sup>, דהיינו בכל המצרים וגבולים<sup data-n=\"8009\">64</sup> הי' יוסף שולט ומושל עליהם ע\"י שאמר פרעה אני וע\"י הסרת הטבעת<sup data-n=\"8010\">65</sup>, דהנה מצינו בכמה גאולת<sup data-n=\"8011\">66</sup> הסרת הטבעת כמו באחשורש שנתן הטבעת למרדכי<sup data-n=\"8012\">67</sup>, אך תחלה הי' אצל המן<sup data-n=\"8013\">68</sup> מפני שכדי שיתגלה פנימי' נקודת הלב הוא ע\"י שבירת ההיפוך המונע ומסתיר, וישראל אז באו לפנימי' נקודת הלב שהרי הי' להם לכולם מס\"נ על נקודת היהדות וכמ\"ש וקבל היהודים ל' יחיד<sup data-n=\"8014\">69</sup> שכולם היו במס\"נ כא' ע\"ד מ\"ש במ\"ת ויחן ישראל וארז\"ל שנעשו כולם כאיש א'<sup data-n=\"8015\">70</sup>, וכמ\"כ ביוסף הי' הסרת הטבעת שענין הטבעת הוא חותם<sup data-n=\"8016\">71</sup> שהוא חותם המלך והו\"ע מ\"ש בזהר גושפנקא דחתים בי' מלכא דחתום בי' שמיא וארעא<sup data-n=\"8017\">72</sup> והוא",[["7997","52","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670403\" data-slug=\"torat-chaim\" data-id=\"2300670403\">שרבקה הוא שם ב</a>\"ן ויצחק . . שם מ\"ה</b>: ראה גם מאמרי אדה\"ז תקס\"ט ע' סז. תו\"ח לך פו, ד ובהערה 13 [ושם: בשם הלקו\"ת]. לעיל מאמר ד\"ה וידבר כו' קדושים תהיו שם. שני המאורות לרי\"א מהאמעל ע' 140."],["7998","53","<b>שם ב\"ן</b>: מובא כמ\"פ בע\"ח ופע\"ח וכו'. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה [נקדישך] וביאור הענין ובהערה 54."],["7999","54","<b>שם מ\"ה</b>: ראה זהר בהקדמה ד, א ובדרך אמת שם. הנסמן במאמרי אדה\"א נ\"ך ע' עא."],["8000","55","<b>ומ\"ה מברר ב\"ן</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."],["8001","56","<b>שב\"ן לאחר הבירור . . משם מ\"ה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380280\" data-slug=\"likkutei-torah\" data-id=\"4001380280\">לקו\"ת בחוקותי מז, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540240\" data-slug=\"torat-chaim\" data-id=\"2300540240\">תו\"ח וארא ח\"א ע, ג</a>. וש\"נ."],["8002","57","<b>והנערה טובת מראה מאד</b>: ח\"ש כד, טז."],["8003","58","<b>ומאד הוא בל\"ג</b>: ראה אגה\"ק סי\"ז. סה\"מ תר\"ם ח\"א ע' תכט. וש\"נ."],["8004","59","<b>ותרד העיינה ותמלא כדה</b>: ח\"ש כד, טז. ראה גם בהנחה שלפנ\"ז על יד הערה 38 ואילך."],["8005","60","<b>אדם הוא אותיות מאד</b>: ראה זהר רע\"מ פינחס רמו, ב. ב\"ר פ\"ח, ה. פ\"ט, יב."],["8006","61","<b>מאני של בו\"ד . . הקב\"ה</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה זכור את יום השבת רפ\"ה. וש\"נ."],["8007","62","<b>אני פרעה</b>: מקץ מא, מד."],["8008","63","<b>ומושל על כל ארץ מצרים</b>: ע\"פ ויגש מה, כו."],["8009","64","<b>מצרים . . המצרים וגבולים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370287\" data-slug=\"torah-or\" data-id=\"3901370287\">תו\"א בשלח סד, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">סע\"ג. יתרו סז, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370318\" data-slug=\"torah-or\" data-id=\"3901370318\">עא, ג</a>."],["8010","65","<b>הסרת הטבעת</b>: מקץ מא, מב."],["8011","66","<b>גאולת</b>: כ\"ה בהכת\"י."],["8012","67","<b>נתן הטבעת למרדכי</b>: אסתר ח, ב."],["8013","68","<b>תחלה הי' אצל המן</b>: אסתר שם. ג, י."],["8014","69","<b>וקבל היהודים ל' יחיד</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370437\" data-slug=\"torah-or\" data-id=\"3901370437\">תו\"א מג\"א צז, סע\"ד</a> ואילך."],["8015","70","<b>ויחן ישראל . . כאיש א'</b>: ראה יתרו יט, ב (בדילוג] וברש\"י שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211104\" data-slug=\"likkutei-sichot\" data-id=\"1300211104\">לקו\"ש יתרו כרך כא ע' 104</a>."],["8016","71","<b>הטבעת הוא חותם</b>: ראה רמב\"ן מקץ מא, מב."],["8017","72","<b>בזהר גושפנקא . . שמיא וארעא</b>: ראה עמה\"מ ש\"ו שער עולם התוהו ספ\"ד טו, ג בשם הזהר."]]],[2001910667,"השם אהו\"ה היוצא מר\"ת דאת השמים ואת הארץ<sup data-n=\"8018\">73</sup>, ויוסף זכה לטבעת הזה כי יוסף הוא תוס' אורות<sup data-n=\"8019\">74</sup>, ועי\"ז נעשה שולט ומושל על כל מצרים שע\"י זה הגילוי יסיר כל ההעלמות וההסתרים וע\"י אמירת אני, מכ\"ש כאשר יתגלה גילוי אני של הקב\"ה א\"ס עצמותו ומהותו שיזכו נש\"י שהוא<sup data-n=\"8020\">*75</sup> בבחי' כלה לגדולה זאת להיות בבחי' עטרה להחתן והאור הזה הוא גנוז עכשיו במצות של עכשיו. וזהו מה שמסיים בכל המצות אני הוי', שלכאורה אינו מובן<sup data-n=\"8021\">75</sup> דהתינח אם אדם אומר על עצמו אני הרי הוא ידוע מי הוא ואומר אני הידוע הוא האומר אבל א\"ס אינו מושג ומי הוא האני שאומר, אך הפי' הוא אני א\"ס עצמותו ומהותו שיתגלה לע\"ל ישנו כעת במעשה המצות ולכן לא יהי' עוד מ\"ת<sup data-n=\"8022\">76</sup> כ\"א שיתגלה האור הגנוז עכשיו בהתומ\"צ ולכן ע\"י הקדושין דתומ\"צ דכעת יזכו לגילוי העצום דלע\"ל.\n<b>ובזה</b> יובן מ\"ש רני עקרה לא ילדה, דהרינה הוא ממה שהלא הוא בבחי' לידה, והענין דהנה כתי' בכל צרתם לו צר<sup data-n=\"8023\">77</sup> ויש בזה קרי וכתיב באל\"ף ובוא\"ו, והנה הפי' באל\"ף הוא שאינו נוגע לו כלל ובוא\"ו הוא שנוגע לו כביכול צרתם של ישראל, ונושא הפסוק מורה כך דהכתיב אח\"כ ומלאך פניו הושיעם, וכן בפ' ולו אנחנו עמו<sup data-n=\"8024\">78</sup>, וכן ולו נתכנו עלילות<sup data-n=\"8025\">79</sup> יש ג\"כ קרי וכתיב, והנה שניהם אמת כי אל\"ף מורה על פלא<sup data-n=\"8026\">80</sup> עליון ושם אינו נוגע מעשה התחתונים כחשכה כאורה<sup data-n=\"8027\">81</sup> בשני כפי\"ן לא די שהחשך שוה לאור אלא שגם האור שוה לחשך וכמ\"ש אם צדקת מה תתן<sup data-n=\"8028\">82</sup> כו' ואם חטאת<sup data-n=\"8029\">83</sup> כו', אבל במדריגת וא\"ו ז\"א<sup data-n=\"8030\">84</sup> שם נוגע מדות<sup data-n=\"8031\">85</sup> התחתונים, אך הנה כתיב ונתתם לי אות אמת<sup data-n=\"8032\">86</sup> ואי' בזהר שהוא אות וא\"ו<sup data-n=\"8033\">87</sup> שהוא ענין בריח התיכון",[["8018","73","<b>אהו\"ה . . דאת השמים ואת הארץ</b>: בראשית א, א. ירמי' כג, כד. ראה השמטות לזח\"א רנא, א. מאמרי אדה\"א דברים ח\"ג ע' תתקעד. וש\"נ. ש\"א פה, ב ובהערה 14."],["8019","74","<b>יוסף הוא תוס' אורות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680281\" data-slug=\"torat-chaim\" data-id=\"2300680281\">תו\"ח ויגש רלד, ב</a> ובהערה 18. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480295\" data-slug=\"or-hatorah-hb\" data-id=\"8316480295\">אוה\"ת מקץ כרך ה ע' תתקעט</a>."],["8020","*75","<b>שהוא</b>: כ\"ה בהכת\"י."],["8021","75","<b>אני הוי' שלכאורה אינו מובן</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ועבדתם את הוי' אלקיכם ובהערה 19."],["8022","76","<b>לא יהי' עוד מ\"ת</b>: ראה (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אז ישיר משה ובהערה 71."],["8023","77","<b>בכל צרתם לו צר</b>: ישעי' סג, ט. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תש ובהנסמן במ\"מ לשם. שה\"א ב, ב ובהערה 17. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540089\" data-slug=\"torat-chaim\" data-id=\"2300540089\">תו\"ח וארא ח\"א נא, ד</a>."],["8024","78","<b>ולו אנחנו עמו</b>: תהלים ק, ג. ראה מאמרי אדה\"א דברים ח\"ג ע' תתיג. ח\"ד ע' א'קע. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670467\" data-slug=\"torat-chaim\" data-id=\"2300670467\">תו\"ח לך פח, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550513\" data-slug=\"torat-chaim\" data-id=\"2300550513\">יתרו ח\"ב רסב, א</a>."],["8025","79","<b>ולו נתכנו עלילות</b>: שמו\"א ב, ד. ראה מאמרי אדה\"א נ\"ך ע' תרא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670476\" data-slug=\"torat-chaim\" data-id=\"2300670476\">תו\"ח לך פח, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680378\" data-slug=\"torat-chaim\" data-id=\"2300680378\">תולדות קנה, ד</a>. יתרו שם."],["8026","80","<b>אל\"ף מורה על פלא</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה והי' אור הלבנה ספ\"א. וש\"נ."],["8027","81","<b>כחשכה כאורה</b>: תהלים קלט, יב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380124\" data-slug=\"likkutei-torah\" data-id=\"4001380124\">לקו\"ת צו יב, א</a>. סה\"מ תר\"ם ח\"א ע' שו. וש\"נ."],["8028","82","<b>אם צדקת מה תתן</b>: איוב לה, ז."],["8029","83","<b>ואם חטאת</b>: איוב שם, ו [ושם: אם]."],["8030","84","<b>וא\"ו ז\"א</b>: ראה ע\"ח שער סדר אצי' ש\"ג, פ\"א."],["8031","85","<b>מדות</b>: כ\"ה בהכת\"י."],["8032","86","<b>ונתתם לי אות אמת</b>: יהושע ב, יב."],["8033","87","<b>שהוא אות וא\"ו</b>: ראה זהר ויקרא ב, א. ויחי רמא, ב. מאמרי אדה\"ז תקס\"ה ח\"א ע' שסח ואילך. מאמרי אדה\"א הנחות תקע\"ז ע' ח ואילך. ביאוה\"ז להצ\"צ ויקרא כרך א ע' שיג ואילך."]]],[2001910668,"המבריח מן הקצה אל הקצה<sup data-n=\"8034\">88</sup> הרי קצה התחתון נוגע לקצה העליון, ולכן אי' בזהר אע\"ג דכתיב לא צר באל\"ף עקתא דישראל מטיא להתם<sup data-n=\"8035\">89</sup>, ולא שנוגע שם כלל, דהרי כתיב שחת לא לו<sup data-n=\"8036\">90</sup>, אלא מפני שקצה התחתון נוגע לקצה העליון. והנה כתי' ושרי אשת אברם לא ילדה לו<sup data-n=\"8037\">91</sup> ושם הוא הפי' שלא ילדה כלל ואח\"כ כתי' ושרי עקרה אין לה ולד<sup data-n=\"8038\">92</sup> ואי' במד\"ר כ\"מ שנאמר אין לה הווה לה<sup data-n=\"8039\">93</sup>, ציון דורש אין לה<sup data-n=\"8040\">94</sup> והווה לה, ולחנה אין לה ילדים<sup data-n=\"8041\">95</sup> והווה לה, ושרי עקרה אין לה ולד הווה לה, דהנה פי' אין הוא האין שהוא הלא באל\"ף הממלא כל החסרונות<sup data-n=\"8042\">96</sup> וכמ\"ש כי אין מחסור ליראיו<sup data-n=\"8043\">97</sup>, כי הנה כתיב בערום ובחוסר כל<sup data-n=\"8044\">98</sup>, שחסר הכל שמעין עוה\"ב כמ\"ש כל אשר תאמר אליך שרה כו', שגילוי זה בא מחמת התבוננות דמרוב כל<sup data-n=\"8045\">99</sup>, אבל האין ממלא החוסר דכל, דכאשר מאיר ומתגלה גילוי האל\"ף הרי ממילא נתמלא כל החסרונות, וזהו הרינה ממה שהלא שהוא האין הוא בבחי' לידה שהוא גילוי, אך עיקר גילוי זה יהי' לע\"ל כי גלות נמשל לעיבור וגאולה ללידה<sup data-n=\"8046\">100</sup>.\n<b>וזהו</b> מ\"ש שוש תשיש שמשמח אחרים שלע\"ל יהי' גילוי פנימי' טעמי תורה ממילא יהי' גילוי רצון ג\"כ באופן אחר ומחמת זה יגיע השמחה גם להקב\"ה, וכמאמר רז\"ל ע\"פ ישמח ה' במעשיו<sup data-n=\"8047\">101</sup> שמח לא נאמר אלא ישמח עתיד הקב\"ה לשמוח במעשיהם של צדיקים לע\"ל, ופי' קוב\"ה הרי ידוע דהוא מרמז על כללות השתלשלות דע\"ס, וכאשר יהי' גילוי האין דכ\"ע בע\"ס אז יהי' בהם גילוי השמחה, וזהו ותגל העקרה והוא מהגילוי דלא ילדה, והגילוי הזה שיהי' הוא מחמת קיבוץ בניה לתוכה והוא ע\"ש מ\"ש ברחמים גדולים כו', כי יש ב' בחי' רחמים, אב הרחמן ואב הרחמים<sup data-n=\"8048\">102</sup>, אב הרחמן הוא הרחמים שבסדר השתלשלות שכנגד החסד והרחמים יש מדה\"ד אבל אב הרחמים הוא רחמים פשוטים שבכתר, ומחמת גילוי זה הרחמים יתגלה גילוי האין ואז יהי' השמחה שלימה בכנס\"י ובקוב\"ה. וזהו שייכות",[["8034","88","<b>בריח התיכון . . אל הקצה</b>: ע\"פ תרומה כו, כח. ויקהל לו,לג."],["8035","89","<b>עקתא דישראל מטיא להתם</b>: ראה זהר וירא קכ, ב."],["8036","90","<b>שחת לא לו</b>: האזינו לב, ה [ושם: לו לא — ראה גם סה\"מ תרל\"ג ח\"ב ע' תקכא. ריש ע' תקצד]."],["8037","91","<b>ושרי אשת אברם לא ילדה לו</b>: לך טז, א."],["8038","92","<b>ושרי עקרה אין לה ולד</b>: נח יא, ל [ושם: ותהי שרי]."],["8039","93","<b>כ\"מ שנאמר אין לה הוה לה</b>: ראה ב\"ר ספל\"ח. (לעיל בחלק המאמרים) מאמר ד\"ה והנה תורה היא בחי' קו האמצעי ובהערה 216."],["8040","94","<b>ציון דורש אין לה</b>: ירמי' ל, יז [ושם: ציון היא. ראה גם לעיל שם ובהערה 223]."],["8041","95","<b>ולחנה אין לה ילדים</b>: שמו\"א א, ב [ושם: ולחנה אין ילדים. ראה גם לעיל שם ובהערה 222]."],["8042","96","<b>האין . . הממלא כל החסרונות</b>: ראה גם לעיל שם ובהערה 235."],["8043","97","<b>כי אין מחסור ליריאיו</b>: תהלים לד, י."],["8044","98","<b>בערום ובחוסר כל</b>: תבא כח, מח [ושם: ובעירום. ראה גם לעיל שם על יד הערה 236]."],["8045","99","<b>מרוב כל</b>: תבא שם, מז."],["8046","100","<b>גלות נמשל לעיבור . . ללידה</b>: ראה תו\"א ר\"פ וארא. תו\"ח שמו ח\"א יז, ג. וש\"נ."],["8047","101","<b>ישמח ה' במעשיו</b>: תהלים קד, לא. ראה ויק\"ר פ\"כ, ב. לקו\"ת שמע\"צ פט, א ואילך. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650264\" data-slug=\"or-hatorah-hb\" data-id=\"8316650264\">אוה\"ת שבועות ע' קלד</a> ואילך — נדפס גם באוה\"ת תהלים כרך ב ע' תתקצג."],["8048","102","<b>אב הרחמן ואב הרחמים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380970\" data-slug=\"likkutei-torah\" data-id=\"4001380970\">לקו\"ת ר\"ה סב, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380400\" data-slug=\"likkutei-torah\" data-id=\"4001380400\">נשא כג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381171\" data-slug=\"likkutei-torah\" data-id=\"4001381171\">שה\"ש י, סע\"ג</a> ואילך. סה\"מ תר\"ם ח\"א ע' רפה. וש\"נ."]]],[2001910669,"ברכת שוש כו' העקרה לזכרון ירושלים, כי ירושלים הוא הדבור עליון שהיא כנס\"י שעכשיו היא בבחי' עקרה, אבל לע\"ל יתעלה בחי' כלה ואז יהי' לידה לעקרה הנ\"ל ויצאו ממנה מים חיים לים הקדמוני וזהו זכרון ירושלים, אך כעת צ\"ל כסדר המדריגות, תחלה צ\"ל משמח חתן וכלה שעכשיו צ\"ל העטרה ע\"י קיום התורה ומצות ועי\"ז יהי' לע\"ל כנס\"י העטרה בעצמה ואז יהי' עיקר שמחת הכלה והחתן יקבל ממנה השמחה, וזהו משמח חתן עם הכלה, ואז ישיש עליך אלהיך כמשוש חתן על כלה<sup data-n=\"8049\">103</sup>.",[["8049","103","<b>כמשוש חתן על כלה</b>: ישעי' סב, ה [ושם: ומשוש — ראה גם בהנחה שלפנ\"ז ובהערה 8]."]]],[2001910670,"<h3>תקעו בחדש שופר</h3>\n<b></b><b>בס\"ד ר\"ה נאמר בליל ב' ש' תרמ\"ב</b>\n<b>תקעו</b> בחדש שופר<sup data-n=\"8050\">1</sup> בכסה ליום חגנו<sup data-n=\"8051\">2</sup>, הנה לכאורה צ\"ל מפני מה נאמר בחדש סתם ולא נא' באיזה חדש כמו שנא' בתורה ובחדש השביעי באחד לחדש ואח\"כ נא' יום תרועה<sup data-n=\"8052\">3</sup> יהי' לכם, והגם שרז\"ל דרשו מבכסה ליום חגנו איזהו חג שהחדש מתכסה בו<sup data-n=\"8053\">4</sup> הוי אומר זה ר\"ה א\"כ מובן שהזמן הוא בחודש השביעי, מ\"מ אינו מובן למה נא' סתם וצריך ליתן אח\"כ סימן ע\"ז, מפני מה לא נא' בפירוש בחודש השביעי. לכאורה בתושב\"כ הי' צריך לכתוב סתם בחדש ודוד הי' צריך לפרש, ובאמת הוא להיפך שבתושב\"כ נא' בחדש השביעי בפירוש ודוד אמר סתם בחדש רק שנתן סימן כו'. גם צ\"ל מהו\"ע קריאת שם ר\"ה הלא בתורה נק' יום תרועה, יום זכרון תרועה<sup data-n=\"8054\">5</sup>, וביחזקאל נא' קריאת שם ר\"ה<sup data-n=\"8055\">6</sup>, מפני מה לא נק' יום הזכרון כו'.\n<b>להבין</b> זאת, הנה מ\"ש בחדש, חדש הוא לשון התחדשות<sup data-n=\"8056\">7</sup>, שבר\"ה נמשך חיות כללי על כללית השנה<sup data-n=\"8057\">8</sup>, שערב ר\"ה עם חשיכה נסתלק החיות<sup data-n=\"8058\">9</sup> משנה העברה ונמשך חיות מחדש על כללית, השנה וזהו חדש לשון התחדשות שנתחדש החיות",[["8050","1","<b>תקעו בחודש שופר</b>: לע\"ע מצאנו רק שני הנחות מדרוש זה, והם: א) גוכתי\"ק כ\"ק אדמו\"ר מהורש\"ב, נדפסה לעיל בחלק הנחותיו. ב) הנחה אחרת, והיא הנדפסת כאן."],["8051","2","<b>תקעו בחדש שופר בכסה ליום חגנו</b>: תהלים פא, ה."],["8052","3","<b>ובחדש השביעי . . יום תרועה</b>: פינחס כט, א. ראה לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב שמביא הכתוב: בחדש השביעי — אמור כג, כד."],["8053","4","<b>איזהו חג שהחדש מתכסה בו</b>: ר\"ה ח, סע\"א ואילך."],["8054","5","<b>יום זכרון תרועה</b>: אמור כג, כד [בהוספת תיבת: יום — ראה גם לקמן בסיום המאמר]. ראה גם אוה\"ת ר\"ה ע' א' שיז ואילך."],["8055","6","<b>וביחזקאל נא' קריאת שם ר\"ה</b>: מ, א."],["8056","7","<b>חדש הוא לשון התחדשות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380907\" data-slug=\"likkutei-torah\" data-id=\"4001380907\">לקו\"ת נצבים מז, א</a>."],["8057","8","<b>שבר\"ה נמשך חיות . . כללית השנה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380904\" data-slug=\"likkutei-torah\" data-id=\"4001380904\">לקו\"ת שם מו, ב</a>. רע\"ד. מאמרי אדה\"ז תקס\"ו ע' רסג. ע' שצ."],["8058","9","<b>שערב ר\"ה עם חשיכה נסתלק החיות</b>: ראה אגה\"ק סי\"ד (קכ, ב. קכא, רע\"א). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380934\" data-slug=\"likkutei-torah\" data-id=\"4001380934\">לקו\"ת ר\"ה נג, ד</a>. המשך וככה תרל\"ז רפפ\"א. סה\"מ תר\"ם ח\"ב ע' תקמא. ע' תרעה. תשי\"א ע' 33. סה\"מ מלוקט ה' ע' ה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091220\" data-slug=\"likkutei-sichot\" data-id=\"1300091220\">לקו\"ש האזינו כרך ט ע' 220</a>."]]],[2001910671,"בר\"ה. וזהו עד\"מ מבשרי אחזה<sup data-n=\"8059\">10</sup>, כמו באדם יש רמ\"ח אברים<sup data-n=\"8060\">11</sup> פרטי' שכל אבר פועל פעולתו פרטיות, ויש אברים כללים שהם כללית החיות מכל האברים, וע\"כ האברים כללים אינם נמנה ברמ\"ח אברים מפני שהם כללים. וזהו הפלוגתא דר\"א ור\"י היכן החכמה שרוי'<sup data-n=\"8061\">12</sup> ר\"א אומר במוח שבראש ור\"י אומר החכמה שרוי' בלב, והם נמשכים אחר דוד ושלמה, דוד אומר ששרוי' בראש ושלמה אומר בלב, ובאמת שניהם הם כללים, פי' היכן החכמה שרוי' כי הנה כתי' ראשית חכמה<sup data-n=\"8062\">13</sup> שחכמה נק' ראשית, כי בחכמה יש השראת אוא\"ס<sup data-n=\"8063\">14</sup> וע\"כ נק' ראשית, וכתי' והחכמה תחי'<sup data-n=\"8064\">15</sup> שחכמה הוא החיות ועיקר החיות הוא במוח<sup data-n=\"8065\">16</sup>, ע\"כ לפי דעת ר\"א הראש אינו נמנה ברמ\"ח אברים, ולפי דעת ר\"י הלב הוא הכלל ע\"כ הלב אינו נמנה כו'. הגם שיש התפשטות אפי' בצפורן הרגל, מ\"מ עיקר השראה הוא במוח או בלב בהכללים כו'. וכ\"ז הוא בנפש כן יובן בעולם שנה ג\"כ.\n<b>ויש</b> להבין תחלה בעולם. הנה יעקב אמר אכן יש ה' במקום הזה ואנכי לא ידעתי<sup data-n=\"8066\">17</sup> ויירא ויאמר מה נורא המקום הזה אין זה כ\"א בית אלקים<sup data-n=\"8067\">18</sup>, לכאורה צ\"ל מה נתפעל יעקב מה שאמר אכן יש הוי' הלא כתי' את השמים ואת הארץ אני מלא<sup data-n=\"8068\">19</sup> שנושא מתיבת אני מורה על עצמיות שלמעלה משם הוי' כי שם הוי' הוא רק שם כמ\"ש אני ה' הוא שמי<sup data-n=\"8069\">20</sup>, רק ששם ה' הוא שם העצם<sup data-n=\"8070\">21</sup>, אבל זהו רק שם, אבל אני מורה על עצמיות, ובשמו\"א אני מלא, וכן כתי' מלא כה\"כ<sup data-n=\"8071\">22</sup> וכן בזוהר איתא לית אתר פנוי מיני'<sup data-n=\"8072\">23</sup>, וכן במד\"ר דרשו ע\"פ וירא מלאך ה' אליו כו' מתוך הסנה<sup data-n=\"8073\">24</sup>",[["8059","10","<b>מבשרי אחזה</b>: ע\"פ איוב יט, כו."],["8060","11","<b>באדם יש רמ\"ח אברים</b>: אהלות פ\"א, מ\"ח."],["8061","12","<b>דר\"א ור\"י היכן החכמה שרוי'</b>: לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן: ”בילקוט ריש משלי\" — ראה שם א, א (רמז תתקכט). מדרש משלי שם (ובשניהם: היכן (היא) החכ' מצוי']. ראה גם סה\"מ תרל\"ח ס\"ע תסב ואילך. וש\"נ."],["8062","13","<b>ראשית חכמה</b>: תהלים קיא, י. ראה גם מאמרי אדה\"א בראשית ע' א. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550075\" data-slug=\"torat-chaim\" data-id=\"2300550075\">תו\"ח יתרו ח\"ב רסד, ב</a>. וש\"נ."],["8063","14","<b>בחכמה יש השראת אוא\"ס</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה שלש רגלים תחוג לי ובהערה 120."],["8064","15","<b>והחכ' תחי'</b>: קהלת ז, יב [ושם: החכמה — ראה גם לעיל שם מאמר ד\"ה ובירך את לחמך ובהערה 10]."],["8065","16","<b>ועיקר החיות הוא במוח</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310056\" data-slug=\"tanya\" data-id=\"3401310056\">תניא פנ\"א</a>. ראה גם לעיל שם מאמר ד\"ה הקבצו ושמעו בנ\"י על יד הערה 115 ואילך."],["8066","17","<b>אכן יש ה' . . לא ידעתי</b>: ויצא כח, טז. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה קדש ישראל לה' פ\"ב ובהנסמן שם."],["8067","18","<b>ויירא ויאמר . . בית אלקים</b>: ויצא שם, יז."],["8068","19","<b>את השמים . . אני מלא</b>: ירמי' כג, כד."],["8069","20","<b>אני ה' הוא שמי</b>: ישעי' מב, ח. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ראה קראתי בשם רפ\"ד."],["8070","21","<b>ששם ה' הוא שם העצם</b>: ראה כ\"מ לרמב\"ם הל' ע\"ז פ\"ב, ה\"ז. פרדס שער שם בן ד' שי\"ט, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' תכו. (לעיל בחלק המאמרים) מאמר ד\"ה ועבדתם את הוי' אלקיכם בסופו."],["8071","22","<b>מלא כה\"כ</b>: ישעי' ו, ג."],["8072","23","<b>לית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>. שם בהוספות נב, ג."],["8073","24","<b>במד\"ר . . וירא מלאך . . מתוך הסנה</b>: שמות ג, ב. שמו\"ר פ\"ב, ה. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה קדש ישראל לה' ובהערה 78."]]],[2001910672,"ללמדך שאין מקום פנוי בלא שכינה אפי' סנה, א\"כ מה נתפעל יעקב אכן יש ה' ואנכי לא ידעתי כו'. אך הענין הוא הנה ת\"א פי' ע\"פ לית דין אתר הדיוט<sup data-n=\"8074\">25</sup>, פי' הנה ע\"מ נק' מילין דהדיוטא כמארז\"ל לאו אורחא דמלכא לאשתעי במילין דהדיוטא<sup data-n=\"8075\">26</sup>, שעש\"מ שהם מקור התהוות העולמות נק' מילין דהדיוטא ומכ\"ש שכללית השפעה שנשפע בנבראים ונוצרים ונעשים בודאי נק' מילין דהדיוטא, וכן מט\"ט שהוא שרו ש\"ע<sup data-n=\"8076\">27</sup> שע\"י נמשך כגרזן ביד החוצב בו<sup data-n=\"8078\">29</sup><sup data-n=\"8077\">28</sup> נק' הדיוט הוא לגבי מרא<sup data-n=\"8079\">30</sup>, הגם שנק' הדיוט רק לגבי מרא מ\"מ נק' הדיוט, א\"כ יובן מזה שעש\"מ נק' מילין דהדיוטא ומכ\"ש שהשפעה שנשפע בעולמות בודאי נק' הדיוט כו', אבל מקום בהמ\"ק לית דין אתר הדיוט, יש ה' במקום הזה. כי הנה הגם את השמים ואת הארץ אני מלא זהו רק בהעלם, כי לכאורה איך מותר במלאכה<sup data-n=\"8080\">31</sup> הלא ארז\"ל מאן דמחוי במחוג<sup data-n=\"8081\">32</sup> קמי' מלכא קטלא חייב ואיך מותר במלאכה, אלא מפני מ\"ש אני מלא זהו רק בהעלם ע\"כ מותר במלאכה. ועוד א\"ל מפני שמאיר בבחי' מקיף וענין המקיף היינו שמאיר בהעלם ולא בבחי' אור פנימי בגילוי, אבל במקום בהמ\"ק הי' מאיר בגילוי, יש ה', היינו שמאיר בגילוי. והיינו כמו שאנו רואים באדם שהגם שיש רצון אפי' ברגל והראי' תיכף כשעולה ברצונו לנענע הוא מנענע בלא שיהוי זמן<sup data-n=\"8082\">33</sup> ואם שהרצון הוא דוקא בראש צריך ע\"ז שיהוי זמן עד שיומשך מהראש ברגל אלא צריך לומר שיש רצון אפי' ברגל ג\"כ ע\"כ תיכף כשעולה ברצונו לנענע הוא מתנענע בלא שיהוי זמן, אך זהו רק התפשטות אבל עיקר השראת הרצון הוא בראש, שברגל הוא רק התפשטות ובראש הוא עיקר השראה, כן יובן מ\"ש את השמים ואת הארץ אני מלא זהו רק בהעלם, אבל בבהמ\"ק הי' מאיר גילוי בחי' ד\"ע כידוע שבבהמ\"ק הי' נקרא שם הוי' ככתבו<sup data-n=\"8083\">34</sup> ובמדינה בכינוי' בשם אד', אבל בבהמ\"ק ככתבו בחי' ד\"ע כו', א\"כ כמו הראש באדם כמו\"כ בהמ\"ק הוא בחי' ראש מעולם ע\"כ התפעל יעקב אכן יש ה' במקום הזה.",[["8074","25","<b>ת\"א . . לית דין אתר הדיוט</b>: לויצא כח, יז. ראה אוה\"ת בא כרך ז ע' ב'תרכד."],["8075","26","<b>ע\"מ . . לאו אורחא . . דהדיוטא</b>: ראה זהר בהעלותך קמט, ב. סידור שער התפלה יח, סע\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380187\" data-slug=\"likkutei-torah\" data-id=\"4001380187\">לקו\"ת אחרי כה, ד</a>. (לעיל בחלק המאמרים) מאמר ד\"ה קדש ישראל לה' פ\"ב הערה 83."],["8076","27","<b>מט\"ט שהוא שרו ש\"ע</b>: ראה יבמות טז, ב ובתוס' שם. מאמרי אדה\"א ויקרא ח\"ב ע' תתעא. במדבר ח\"ב ע' תשצ. דברים ח\"ג ע' תשצד. סה\"מ תר\"ם ח\"א ע' ד. וש\"נ."],["8078","29","<b>כגרזן ביד החוצב בו</b>: מו\"נ ח\"ג פכ\"ט. זהר בראשית לו, א. ישעי' י, טו."],["8077","28","<b>מט\"ט . . כגרזן ביד החוצב בו</b>: ראה גם סה\"מ תר\"ם ח\"א שם. ח\"ב ע' תרפ. ולהעיר מסה\"מ תרכ\"ט ע' קסה."],["8079","30","<b>הדיוט הוא לגבי מרא</b>: ראה זהר רע\"מ תצא רעו, א."],["8080","31","<b>איך מותר במלאכה</b>: ראה גם סידור שער המילה קמה, ד ואילך. סהמ\"צ להצ\"צ ע' ח. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490101\" data-slug=\"or-hatorah-hb\" data-id=\"8316490101\">אוה\"ת לך כרך ד ע' תשכ</a> פ\"ד. סה\"מ תר\"ם ח\"ב ע' תקלד. וש\"נ. פר\"ת ע' קצא. ס\"ע קצג ואילך."],["8081","32","<b>מאן דמחוי במחוג</b>: ראה חגיגה ה, ב."],["8082","33","<b>שיש רצון . . בלא שיהוי זמן</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380140\" data-slug=\"likkutei-torah\" data-id=\"4001380140\">לקו\"ת צו טז, א</a>. מאמרי אדה\"ז על פרשיות התורה ח\"ב ריש ע' תרעט. סהמ\"צ להצ\"צ פה, ב. סה\"מ תרל\"ח ע' רנ. וש\"נ. ע' תסג. וש\"נ."],["8083","34","<b>שבבהמ\"ק . . שם הוי' ככתבו</b>: תמיד פ\"ז, מ\"ב. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ראה קראתי בשם ספ\"ד."]]],[2001910673,"<b>וכן</b> בשנה ר\"ה הוא בחי' ראש, כי הגם שכתי' ובטובו מחדש בכי\"ת<sup data-n=\"8084\">35</sup>, ובאמת לאו דוקא בכל יום אלא בכ\"ע ובכל רגע נמשך חיות חדש מאין ליש, רק מה שנא' בכל יום מפני שזה אנו רואים שמאפיל ומאיר, כמו ששת ימי\"ב שנא' ערב ובקר<sup data-n=\"8085\">36</sup>, ע\"כ בכ\"י שבכ\"י מחדש מאין ליש, וכן כתי' לעולם ה' דברך נצב בשמים<sup data-n=\"8086\">37</sup> שדבר ה' עומד תמיד להחיות<sup data-n=\"8087\">38</sup>, אך זהו רק פרטי' כמו רמ\"ח איברי' פרטי' הגם שכל אבר פועל פעולתו אך זהו רק פרטי' כך מה שכ\"י הוא מחדש זהו רק פרטי' אבל ר\"ה נמשך חיות כללי על כללית השנה א\"כ הוא הראש מכל השנה, וזהו בחדש לשון התחדשות. אך כדי שיתחדש בעש\"נ היינו ע\"י אמרו לפני'<sup data-n=\"8089\">40</sup> מלכיות כדי שתמליכוני עליכם, זכרונות כדי שיעלה זכרוניכם לפני, פי' אמרו לפני כמו את ה' האמרת היום<sup data-n=\"8090\">41</sup>, פי' ענין אמירה כמו למשל כאשר א' אומר לחבירו קודם שאמר בהעלם אצל חבירו אבל כאשר אמר אז נתגלה מהעלם אל הגילוי, האמרת היינו מפעיל פועל יוצא, וזהו אמרו לפני שפועל שיתגלה בחי' רצון אנא אמלוך<sup data-n=\"8091\">*42</sup>, זכרונות כדי שיעלה זכרוניכם לפני, מפני כי כללית השתלשלות העולמות אינו תופס מקום רק הארה בעלמא ע\"כ שייך ע\"ז זכרונות, הגם שאין שכחה לפני כסא כבודך<sup data-n=\"8092\">42</sup>, ששכחה אינו שייך שם, מ\"מ זכרון ג\"כ אינו שייך שאינו תופס מקום, ע\"כ אמרו זכרונות כדי שיעלה זכרוניכם לפני. אך מלכיות וזכרונות תלוי ובמה בשופר<sup data-n=\"8088\">39</sup>, כי שופר צדו א' קצר וצדו א' רחב, מן המיצר קראתי י\"ה<sup data-n=\"8093\">43</sup> ענני במרחב י\"ה.\n<b>להבין</b> זאת הנה רמ\"ח פקודין רמ\"ח אברים דמלכא<sup data-n=\"8094\">44</sup>, הנה ההפרש בין אברים לכלים<sup data-n=\"8095\">45</sup> שענין הכלי הוא רק מחזיק השפע אבל אינו מכריח שיומשך השפע בכלי רק כאשר שופכים בכלי מחזיק הכלי השפע, אבל אברים אינו דומה לכלים שיחזיק החיות כאשר נמשך חיות הנפש, אלא כאשר אין בהם חסרון שהאבר בריא בלא שום חסרון ממילא ומאיליו נמשך חיות הנפש שמכריח חיות הנפש שיומשך באיברים, כך יובן מצות נק' רמ\"ח אברים דמלכא, כמו שהאברים כאשר אין בהם חסרון ממילא נמשך חיות הנפש כן מצות כאשר עושים כדבעי ממשיכים המשכת אוא\"ס, ע\"י תפילין ממשיכים ד' מוחין<sup data-n=\"8096\">46</sup> עליונים, וע\"י ציצית",[["8084","35","<b>ובטובו מחדש בכי\"ת</b>: ברכת יוצר. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה שיר המעלות ממעמקים רפ\"ב. סה\"מ תר\"ם ח\"א ע' ה. וש\"נ."],["8085","36","<b>ששת ימי\"ב שנא' ערב ובקר</b>: בראשית א, ה. ח. יג. יט. כג. לא."],["8086","37","<b>לעולם ה' דברך נצב בשמים</b>: תהלים קיט, פט."],["8087","38","<b>שדבר ה' עומד תמיד להחיות</b>: ראה שער היחוה\"א פ\"א."],["8089","40","<b>לפני'</b>: כנצ\"ל: לפני [כבסמוך בפנים]."],["8090","41","<b>את ה' האמרת היום</b>: תבוא כו, יז."],["8091","*42","<b>אנא אמלוך</b>: ראה לקמן הערה 49."],["8092","42","<b>שאין שכחה לפני כסא כבודך</b>: ברכת זכרונות. ברכות לב, ב."],["8088","39","<b>אמרו לפני' מלכיות . . ובמה בשופר</b>: ראה ר\"ה טז, סע\"א. לד, ב."],["8093","43","<b>מן המיצר קראתי י\"ה</b>: תהלים קיח, ה."],["8094","44","<b>רמ\"ח פקודין . . אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא</a> רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["8095","45","<b>ההפרש בין אברים לכלים</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה שיר המעלות ממעמקים ובהערה 54."],["8096","46","<b>תפילין ממשיכים ד' מוחין</b>: ראה זהר ואתחנן רסב, א. פע\"ח שער התפילין שער ד, פ\"א ואילך. סידור שער התפילין ז, א. מאמרי אדה\"א דברים ח\"ד ע' א'רמא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670598\" data-slug=\"torat-chaim\" data-id=\"2300670598\">תו\"ח נח עח, ד</a> הערה 34."]]],[2001910674,"ל\"ב נ\"ח<sup data-n=\"8097\">47</sup>, הגם שאינו בערך שע\"י קלף גשמי יומשך ד' מוחין עליונים, אך כמו שע\"י אברים הגם שאינו בערך גשם האבר לגבי הרוחני' מ\"מ ע\"י גשמיות נמשך חיות הרוחני', אך זהו רק כמו משל כי באמת כתי' הציבי לך ציונים<sup data-n=\"8098\">48</sup>, שמצות הוא רק ציון וסימן שע\"י קלף גשמי הגם שאינו בערך מ\"מ עי\"ז ממשיכים ד' מוחין עליונים, כי ע\"י עשיי' המצות עי\"ז ממשיכים הרצון מאנא אמלוך<sup data-n=\"8099\">49</sup> שיהי' דירתו ית' בתחתונים כמ\"ש נחת רוח לפני שאמרתי ונעשה רצוני<sup data-n=\"8100\">50</sup>, שצריך לעשות רצון העליון שיהי' רצון, והיינו ע\"י המצות כמ\"ש אנכי עשיתי ארץ<sup data-n=\"8101\">51</sup> ואדם עלי' בראתי שנשפע<sup data-n=\"8102\">52</sup> מאנכי מי שאנכי<sup data-n=\"8103\">53</sup> המכוון הוא בשביל ארץ וארץ בשביל אדם ואדם עלי' בראתי פי' בראתי גימט' תרי\"ג<sup data-n=\"8104\">54</sup>, שע\"י תרי\"ג מצות עי\"ז ממשיכים מאנכי כו' שיומשך מבחי' ה' מלך גאות לבש<sup data-n=\"8105\">55</sup>, וע\"כ שיר זה תיקנו בר\"ה<sup data-n=\"8106\">56</sup>, כי בכ\"ה באלול נברא העולם<sup data-n=\"8107\">57</sup> ור\"ה יום ששי למע\"ב ואז שיר ה' מלך<sup data-n=\"8108\">58</sup>, כי הנה התהוות העולמות הוא רק מע\"מ<sup data-n=\"8109\">59</sup> ובע\"מ לא נזכר שם ה' רק שם אלקים<sup data-n=\"8110\">60</sup>, ל\"ב פעמים אלקים<sup data-n=\"8111\">61</sup>, אבל ע\"י מצות ממשיכים בחי' שם ה', כי ע\"י מ\"ע ממשיכים בחי' ו\"ה וע\"י מל\"ת ממשיכים בחי' י\"ה<sup data-n=\"8112\">62</sup>, וזהו כללית שם ה', ובשם ה' כתי' יהללו את שם ה' כי הוא ציוה ונבראו<sup data-n=\"8113\">63</sup> פי' ונבראו ממילא ומאיליו כו', ובד\"כ זהו ההפרש בין מל' למלכא<sup data-n=\"8114\">64</sup>,",[["8097","47","<b>ציצית ל\"ב נ\"ח</b>: ראה זח\"ג תוספת שא, א. בחיי שלח טו, לח ד\"ה וע\"ד הקבלה (ירושלים תשל\"ב ס\"ע קא). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקטז ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380523\" data-slug=\"likkutei-torah\" data-id=\"4001380523\">לקו\"ת קרח נב, ב</a>. ד."],["8098","48","<b>הציבי לך ציונים</b>: ירמי' לא, כ. ראה גם לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה קדש ישראל לה' ובהערה 140."],["8099","49","<b>מאנא אמלוך</b>: לשון הת\"י למל\"א א, ה. ראה (לעיל בחלק המאמרים) במאמר ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום הערה 17."],["8100","50","<b>נחת רוח . . ונעשה רצוני</b>: ספרי שלח טו, ז. י. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301490060\" data-slug=\"likkutei-sichot\" data-id=\"1301490060\">לקו\"ש ויקרא כרך לב ע' 1</a>. וש\"נ."],["8101","51","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב."],["8102","52","<b>שנשפע</b>: אולי כן הוא בהכת\"י."],["8103","53","<b>מאנכי מי שאנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא מהדו\"ק ספמ\"ט</a>. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["8104","54","<b>בראתי גימט' תרי\"ג</b>: ראה רמ\"ז לזהר ויגש רה, ב. (קז, ב בדפי הספר). לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה קדש ישראל לה' ובהערה 173."],["8105","55","<b>ה' מלך גאות לבש</b>: תהלים צג, א."],["8106","56","<b>ה' מלך . . תיקנו בר\"ה</b>: כנראה הכוונה שאדה\"ר אמרו בר\"ה כדבסמוך:ואז שיר ה' מלך — ראה פדר\"א פי\"א. ר\"ה לא, א. מאמרי אדה\"א דברים ח\"ג ע' תשס. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680110\" data-slug=\"torat-chaim\" data-id=\"2300680110\">תו\"ח וישלח קפא, ד</a> ובהערה 64. בא ח\"א קא, ב."],["8107","57","<b>בכ\"ה באלול נברא העולם</b>: ראה פדר\"א רפ\"ח. מאמרי אדה\"א דברים ח\"ג ע' תתמ. וש\"נ."],["8108","58","<b>יום ששי . . שיר ה' מלך</b>: ר\"ה שם."],["8109","59","<b>התהוות העולמות . . רק מע\"מ</b>: אבות רפ\"ה."],["8110","60","<b>ובע\"מ . . נזכר . . רק שם אלקים</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ועבדתם את ה' אלקיכם ובהערה 37."],["8111","61","<b>ל\"ב פעמים אלקים</b>: נמנו בפרטיות בתקז\"ח קיב, ג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרכה. וש\"נ."],["8112","62","<b>מ\"ע . . ו\"ה . . מל\"ת . . י\"ה</b>: ראה ת\"ז בהקדמה ד, סע\"ב. ה, א. סה\"מ תר\"ם ח\"א ע' תז. וש\"נ."],["8113","63","<b>יהללו . . צוה ונבראו</b>: תהלים קמח, ה. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ועבדתם את ה\"א ובהערה 79."],["8114","64","<b>ההפרש בין מל' למלכא</b>: ראה גם סה\"מ תרכ\"ז ע' תלז."]]],[2001910675,"שהתהוות העולמות הוא רק מבחי' מל' וע\"י מצות ממשיכים בחי' מלכא שהוא למעלה ממקור העולמות.\n<b>וזהו\"ע</b> קריאת שם ר\"ה, שר\"ה הוא דין ומשפט אם העלאת מ\"ן משנה העברה כדבעי, אם ראוי שיומשך בחי' רצון אנא אמלוך, כמ\"ש בע\"ח כשעלה ברצונו הפשוט<sup data-n=\"8115\">65</sup> לברוא את העולם מצד טבע הטוב<sup data-n=\"8117\">67</sup> להטיב<sup data-n=\"8116\">66</sup>, בתחלת הבריאה זהו מצד כי חפץ חסד<sup data-n=\"8118\">68</sup> הוא<sup data-n=\"8119\">69</sup>, פי' חסד כמו שהוא בחפץ, אבל עכשיו תלוי בהעלאת מ\"ן<sup data-n=\"8120\">70</sup>, כאשר העלאת מ\"ן כדבעי אז ממילא נמשך המשכת אלקות מלמעלה, ומצד ריבוי השפעה ברוחני' ממילא נמשך בגשמיות, כמו שמצינו שכל היעודים דלע\"ל נאמר בלשון גשמיות מפני שמרוחני' ממילא נמשך בגשמיות, כמארז\"ל כל אורה האמור באלי'<sup data-n=\"8121\">71</sup> אינו אלא בירידת גשמי' הכתוב מדבר, לכאורה מה שייך אור לגשם, אלא שבשרש הוא אור ולמטה נעשה מזה גשם, שגשם מצמיח כל מיני תענוג, כך כאשר העלאת מ\"ן כדבעי אז נמשך ריבוי השפעה ברוחני' ממילא נמשך בגשמיות כו'. וכ\"ז הוא כאשר מקיים תומ\"צ, אבל כאשר פגם במ\"ע או במל\"ת ממילא א\"א להיות דירתו ית' בתחתונים שיומשך בחי' רצון אנא אמלוך, והעצה לזה תשובה בשופר, כי הנה ענין השופר שהתוקע הוא האדם והוא תוקע בקרן של איל<sup data-n=\"8122\">72</sup> בהמה, והיינו ענין אדם ובהמה תושיע ה'<sup data-n=\"8123\">73</sup>, שע\"י אדם ובהמה עי\"ז תושיע ה' אפי' כאשר פגם כו', כמארז\"ל ערומים בדעת כאדם ונמשכים אחריך כבהמה<sup data-n=\"8124\">74</sup>, פי' ערומים הנה ענין ערמה למעלה מחכמה, כי חכמה היינו שמבין השכל וניכר שהוא מבין (בל\"א עס איז קענטיג), אבל ערמה היינו שמסתיר הענין (בל\"א ער גייט אַרום דיא זאך) רק ממילא ומאילי' נעשה כמו רצונו. א\"כ ערמה למעלה מחכמה, כמ\"ש אני חכמה שכנתי ערמה<sup data-n=\"8125\">75</sup>, שחכמה רק שכן לערמה, כי ערמה למעלה מחכמה כו'.",[["8115","65","<b>כמ\"ש בע\"ח כשעלה ברצונו הפשוט</b>: ראה שם דרוש עגו\"י ש\"א, ענף ב."],["8117","67","<b>טבע הטוב להטיב</b>: ראה עמק המלך שער שעשועי המלך בתחילתו. שומר אמונים ויכוח שני סי\"ד. שער היחוה\"א פ\"ד ובמ\"מ הגהות והע\"ק לשם. ולהעיר משו\"ת חכם צבי סי\"ח."],["8116","66","<b><a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410066\" data-slug=\"likkutei-sichot\" data-id=\"1301410066\">בע\"ח</a> כשעלה . . טבע הטוב להטיב</b>: ראה גם בשם הע\"ח — מאמרי אדה\"א קונטרסים ע' ה. וש\"נ. לקו\"ש בראשית כרך ל ע' 1 הערה 3. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670042\" data-slug=\"torat-chaim\" data-id=\"2300670042\">תו\"ח בראשית ל, ב</a> הערה 4. שמות ח\"א לד, ג הערה 375. סה\"מ תרל\"ח ע' מח. וש\"נ. תר\"ם ח\"א ע' קפו. וש\"נ."],["8118","68","<b>בתחלת הבריאה . . חפץ חסד</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, ספ\"ו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380186\" data-slug=\"likkutei-torah\" data-id=\"4001380186\">לקו\"ת אחרי כה, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380908\" data-slug=\"likkutei-torah\" data-id=\"4001380908\">נצבים מז, ב</a>. שעה\"י פי\"א. ש\"א ל, א הערה 15. סה\"מ תרל\"ח ס\"ע מז ואילך ובהנסמן שם."],["8119","69","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."],["8120","70","<b>עכשיו תלוי בהעלאת מ\"ן</b>: ראה ע\"ח־ לקו\"ת־ וש\"א שבהערה 68."],["8121","71","<b>כל אורה האמור באלי'</b>: ראה ב\"ר ספכ\"ו. סה\"מ תרל\"ח ע' קס. וש\"נ. תר\"ם ח\"ב ס\"ע תשו ואילך. וש\"נ."],["8122","72","<b>תוקע בקרן של איל</b>: ראה ר\"ה טז, א. מאמרי אדה\"א דברים ח\"ג ע' תתצז. וש\"נ."],["8123","73","<b>אדם ובהמה תושיע ה'</b>: תהלים לו, ז."],["8124","74","<b>ערומים בדעת . . כבהמה</b>: ראה חולין ה, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380292\" data-slug=\"likkutei-torah\" data-id=\"4001380292\">לקו\"ת בחוקותי נ, רע\"ג</a>."],["8125","75","<b>אני חכ' שכנתי ערמה</b>: משלי ח, יב. ראה גם סה\"מ תרל\"ב ח\"א ע' קצג. ח\"ב ע' תקסד. תר\"ם ח\"ב ע' תקנב. ע' תתקכד ואילך."]]],[2001910676,"<b>ופי'</b> ערומים בדעת, כי הנה אל דעות ה'<sup data-n=\"8126\">76</sup>, ד\"ע וד\"ת, פי' דעת תחתון היינו בריאה יש מאין לפי שני הפי' אין הארה ואין אינו מושג<sup data-n=\"8127\">77</sup>, זהו רק ד\"ת שם אד' שם אלקי', אבל ד\"ע היינו איך שכולא קמי' כלא חשיב<sup data-n=\"8128\">78</sup>, ומי שהוא קרוב יותר משיג איך שכלא חשיבי, הגם שעכשיו א\"א להשיג רק ד\"ת אבל ד\"ע א\"א להשיג מ\"מ צריך להבין שיש בחי' זו, וזהו ערומים בדעת שצריך להיות ערום בד\"ע כו', ממילא עי\"ז נמשכים אחריך כבהמה שאפשר לבוא לביטול הרצון שלמעלה מטעו\"ד ע\"כ עי\"ז תושיע ה' כו'. כי הנה לפי דעת ר\"י שהלב הוא הכלל ע\"כ כאשר פגם מגיע הפגם בלב ע\"כ צריך תשובה מעומקא דליבא, כי הנה לא מצינו ציווי על מס\"נ בתורה<sup data-n=\"8129\">79</sup> דכתי' לאהבת<sup data-n=\"8130\">80</sup> ה' אלקיך כי הוא חייך<sup data-n=\"8131\">81</sup>, כמו שהאדם אוהב חיי נפשו כן צריך לאהבת ה', אבל על מס\"נ לא מצינו ציווי, ע\"כ ע\"י תשובה מעומקא דליבא רעותא דליבא<sup data-n=\"8132\">82</sup> עי\"ז ממשיכים חיות כללי שלמעלה מכלל דלב, כי לב הגם שהוא כלל זהו רק כלל שייך לפרטים אבל עי\"ז ממשיכים חיות כללי עד שיומשך בעוה\"ז הגשמי כו', וזהו ערומים בדעת כיון שהגיע לבחי' ערמה מובן שכמה שביכולתו להשיג בשכל הגיע עם השגת השכל רק אח\"כ בא לבחי' ערמה, והגם שבא לבחי' ערמה מ\"מ נמשכים אחריך כבהמה ע\"כ עי\"ז ממשיך חיות כללי בכללית העולמות, א\"כ יובן כאשר מקיימים תומ\"צ אז צריך ג\"כ שופר אך זהו רק מצות שופר וכן גנוחי גניח וילולי יליל<sup data-n=\"8133\">83</sup> זהו ג\"כ במצות שופר, אבל כאשר פגם בתומ\"צ צריך תשובה שזהו\"ע צעקה דשופר צדו א' קצר מן המיצר קראתי י\"ה צעקה מעומקא דלבא כמ\"ש ושבת עד ה' אלקיך<sup data-n=\"8134\">84</sup> שיש תשובה בתורה ג\"כ וזהו כולל גם מעומקא דליבא כו', שע\"י שופר ממשיכים בחי' ה' מלך גאות לבש, כי הנה במ' יש שני בחי' היינו בחי' מל' שהוא מקור להתהוות עולמות שם אד', ובחי' הב' היינו המלך המרומם לבדו<sup data-n=\"8135\">85</sup> וע\"י תשובה צעקה דשופר עי\"ז ממשיכים בחי' ה' מלך בחי' המרומם לבדו כו'. וזהו תקעו בחדש שנא' סתם מפני שכולל כללית החיות שנמשך בר\"ה ע\"כ נא' סתם, בתושב\"כ נא' יום תרועה יום זכרון תרועה ואינו מרמז על החיות הכללי מפני שטעמי תורה לא נתגלה<sup data-n=\"8136\">86</sup>, אבל כאן נא' חדש",[["8126","76","<b>אל דעות ה'</b>: שמו\"א ב, ג. ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670564\" data-slug=\"torat-chaim\" data-id=\"2300670564\">תו\"ח בראשית יח, ג</a> ובהערה 11."],["8127","77","<b>אין הארה ואין אינו מושג</b>: ראה גם סה\"מ תרל\"א ח\"א ע' קסט. תרל\"ב ח\"א ע' קה ואילך וע' עדר. תר\"ם ח\"ב ע' תשצ ובהנסמן בהנ\"ל."],["8128","78","<b>שכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["8129","79","<b>לא מצינו ציווי על מס\"נ בתורה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370443\" data-slug=\"torah-or\" data-id=\"3901370443\">תו\"א מג\"א צט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121220\" data-slug=\"likkutei-sichot\" data-id=\"1300121220\">לקו\"ש אמור כרך יב ע' 212</a> ואילך. מאמרי אדה\"א נ\"ך ע' תמה. וש\"נ. סה\"מ תר\"ם ח\"א ע' קעה. וש\"נ."],["8130","80","<b>לאהבת</b>: וכן כתב גם לעיל הנחה ד\"ה שלש רגלים תחג לי על יד הערה 79 — אוצ\"ל: לאהבה את."],["8131","81","<b>לאהבה את . . כי הוא חייך</b>: נצבים ל, כ [בדילוג]."],["8132","82","<b>רעותא דליבא</b>: זהר וירא ק, א."],["8133","83","<b>גנוחי גניח וילולי יליל</b>: ר\"ה לג, ב. לד, א."],["8134","84","<b>ושבת עד ה' אלקיך</b>: ואתחנן ד, ל. נצבים ל, ב."],["8135","85","<b>המלך המרומם לבדו</b>: נוסח ברכת יוצר."],["8136","86","<b>שטעמי תורה לא נתגלה</b>: ראה גם לעיל הנחה ד\"ה שוש תשיש הא' ובהערות 31-32."]]],[2001910677,"סתם מפני שקאי על חיות כללי שנמשך בר\"ה א\"כ דוד פירש יותר ממשה שמשה סתם ודוד פירוש וכתב חדש סתם להראות שבר\"ה נמשך חיות כללי על כללית השנה, והסימן לזה בכסא<sup data-n=\"8137\">87</sup> ליום חגינו, אך כ\"ז הוא ע\"י שופר וזהו תקעו בחדש שופר כו'.",[["8137","87","<b>בכסא</b>: ראה לעיל על יד הערה 2."]]],[2001910678,"<h3>ליקוט מכתבי רבותינו\nאודות שנת תרמ\"א</h3>\n<b>מעלת איש הפשוט</b>\nמכתבו זה הזכירני על הנועם הרוחני אשר זכינו בחסדו ית' להתענג בנעימת שיחת קדש הוד כ\"ק אאמו\"ר הרה\"ק זצוקללה\"ב<sup data-n=\"8138\">1</sup> נבג\"מ זי\"ע<sup data-n=\"8139\">2</sup> בצום גדלי' תרנ\"ט בעת חזרת מאמרי ר\"ה בביאור ענין יתרון הדיבור על שכל ומדות.\n<b>והואיל</b> לספר אשר באחד מאמרי דשנת תרמ\"א הואיל הוד כ\"ק אביו אאזמו\"ר הרה\"ק זצוקלל\"ה נבג\"מ זי\"ע<sup data-n=\"8140\">3</sup> לספר לו מה שסיפר לו הוד כ\"ק אביו אאזמו\"ר הרה\"ק צמח צדק בשם הוד כ\"ק זקנו רבינו הזקן, בעלי מוחין גדולים ובעלי עבודה מיט זודיקע הערצער פאַרשטייען און פילן דעם הפלאת מעלת האיש פשוט באָמרו שמע ישראל ה' אלקינו ה' אחד על מעלת המשכיל, ורחמנא ליבָּא בָּעי<sup data-n=\"8141\">4</sup>.\n<b>מדת האמת ומס\"נ אצל נשמה כללית</b>\nמיין שווער, כ\"ק הרה\"ח ר' אברהם<sup data-n=\"8142\">5</sup> נבג\"מ זי\"ע, האָט געזאָגט להחסיד ר' אשר גראָסמאַן<sup data-n=\"8143\">6</sup>: דער מחותן — הוד כ\"ק אאמו\"ר הרה\"ק — איז זיין, ערשטער טראָט אין עבודת היום מיט מסירת נפש. מיט פינף און צוואַנציג יאָר פריער — תרמ\"א — האָט מיר דער רבי דער פעטער מהר\"ש געזאָגט: זיין אמת און זיין מסירת נפש זיינען שני עמודי אור. — און דער פעטער האָט מסיים געווען: און צו",[["8138","1","כנראה צ\"ל זצוקללה\"ה."],["8139","2","כ\"ק אדמו\"ר מהורש\"ב."],["8140","3","כ\"ק אדמו\"ר מהר\"ש."],["8141","4","מאגרת כ\"ק אדמו\"ר מהוריי\"צ מיום י\"ג טבת תש\"י. נדפסה בס' לגבורה של תורה מאנטרעאל תשמ\"ב ע' 36. מהדו\"ק מהאגרת בתאריך ד' ח' טבת נדפסה באגרות קודש מאת כ\"ק אדמו\"ר מהוריי\"צ חלק יג ע' תקיג."],["8142","5","אודותו סה\"ש תרפ\"ה ע' 81 ובהערה שם. סה\"מ מלוקט א ע' מד בהערה. אגרות קודש מאת כ\"ק אדמו\"ר מהורש\"ב־ ואדמו\"ר מהוריי\"צ כמצויין במפתח אנשים בערכו. סה\"ש תרפ\"ט (במבוא ע' יד) ע' 53. תש\"ו-השי\"ת כמצויין במפתח שמות בערכו. סה\"מ תר\"ם ח\"א ע' . סה\"ש תו\"ש ע' 209. זכרון לבני ישראל עג, ב. כמה ממכתביו נמצאים בארכיון ספריית אגו\"ח."],["8143","6","ר' אשר בר' מאיר שו\"ב מניקולאיעב. ממחונכי ר' הלל מפאריטש ומחסידי אדמו\"ר מהר\"ש נ\"ע ואח\"כ אדמו\"ר מהורש\"ב נ\"ע. התעסק בהגהת התניא דהוצאת ווילנא תר\"ס. נפטר מרחשון ה'תר\"פ (). ספר השיחות קיץ ה'ש\"ת ע' 28. ראה גם סה\"ש תורת שלום ע' 188. אגרות קודש מאת כ\"ק אדמו\"ר מהורש\"ב־ ואדמו\"ר מהוריי\"צ כמצויין במפתח אנשים בערכו. ספר השיחות ה'ש\"ת שם ס\"ע 29. ע' 149. ע' 161. לקו\"ד ח\"א ע' לב. רשימות חוב' קסב ע' 9. סה\"ש תרצ\"ט ע' 307. תש\"א ע' 48. תש\"ב ע' 122-123. תש\"ג ע' 139. ע' 157. ע' 169. תד\"ש ע' 83. תש\"ו-השי\"ת כמצויין במפתח שמות בערכו. סה\"מ תרנ\"ד ע' שנז. שיחת י\"ט כסלו תשי\"ד. שמחת תורה תשט\"ז. צום גדלי' תשנ\"ב. ובאגרותיו כמצויין במפתח אנשים בערכו. מודעה רבה שנדפס בריש ספר התניא. ס' המשפיע ע' רד. דברי ימי התמימים (כרם חב\"ד ג) כמצויין במפתח שמות בערך גרוסמן. כפר חב\"ד גליון 1166 ע' 46. וש\"נ."]]],[2001910679,"וואָס פאַר אַ דרגא אמת און מס\"נ בריינגען קען קיינער ניט משיג זיין, און בפרט דער אמת און מס\"נ פון אַ נשמה כללית.\n<b>יעמאָלט</b> — זאָגט כ\"ק חותני להחסיד ר' אשר נ\"ע — האָב איך געוואוסט אַז ער וועט זיין דער ממלא מקום קדשו<sup data-n=\"8144\">7</sup>.\n<b>לימוד מכל דבר</b>\nהוד כ\"ק אאמו\"ר הרה\"ק<sup data-n=\"8139\">2</sup> האָט מיר דערציילט, אַז צוליב אַ געוויסען ענין בין איך געווען ביום א' דסליחות תרמ\"א ביחידות באַ הוד כ\"ק אאמו\"ר — אאזמו\"ר — הרה\"ק<sup data-n=\"8140\">3</sup> האָט ער מיר געזאָגט:\n<b>פון</b> יעדער זאַך וואָס אַ איד בכלל און אַ חסיד בפרט זעהט אָדער הערט דאַרף ער אַרויסנעמען אַ הוראה אין אַ הנהגה אין עבודת השם, און עבודת השם איז כולל עבודת התפלה, בירור ותיקון המדות און התחלת העבודה איז משעבד זיין די לבושי הנפש מחשבה, דיבור ומעשה<sup data-n=\"8145\">8</sup>.\n<b>אסיפות גדולי ישראל בפעטערבורג</b>\nעס איז געווען אין די יאָהרן תרל\"ט-תרמ\"א וואָס צווישן די פּעטערבורגער מלוכה מענער האָט געוואַקסן די העצע פון פּאָגראָמען און שנאת ישראל<sup data-n=\"8146\">9</sup>.\n<b>אין</b> יענע צייט פלעגן אָפט פאָרקומען אסיפות גדולי ישראל אין פּעטערבורג, וואו עס פלעגען אָנטייל נעמען אויך די פּעטערבורגער גרויסע גבירים.\n<b>אויף</b> איינע פון די אסיפות וואָס עס האָט זיך אַרום גערעדט אַ רעליגיעזע פראַגע, איז אַ פּאָר פון די גרויסע גבירים האָבען זיך אין דער פראַגע אַרויסגעזאָגט ניט מיט דרך-ארץ'דיגען בענעם צו תורה און מצוות.\n<b>איינער</b> פון די גדולי ישראל וואָס האָט זייער פאַר דראָסן דער שלעכטער באַנעם, האָט געזאָגט, אַז הגם די גבירים האַלטן ניט אַזוי, אָבער אויף זייער מיינונג קאָן מען ניט שטעלן, ווייל זייערע עשירות באַלאַנסען שטימען ניט.\n<b>דער</b> וואָרט האָט אויפגעטרייסעלט די גאַנצע אסיפה, און די פּאָר גבירים זענען געוואָרן פאַרציטערטע.\n<b>שלמה</b> המלך — זאָגט דער גדול — האָט גוט געוואוסט וואָס אַ גביר איז, הן",[["8144","7","ספר השיחות תש\"ג ע' 103-102."],["8139","2","כ\"ק אדמו\"ר מהורש\"ב."],["8140","3","כ\"ק אדמו\"ר מהר\"ש."],["8145","8","ספר השיחות תש\"א ע' 145."],["8146","9","ראה ספר התולדות אדמו\"ר מהר\"ש בעריכת כ\"ק אדמו\"ר זי\"ע ע' 17 ואילך. אגרות קודש מאת כ\"ק אדמו\"ר מהוריי\"צ חלק ד ס\"ע תצ ואילך. ספר השיחות קיץ ה'ש\"ת ע' 13 ואילך."]]],[2001910680,"זיין עשירות און הן זיין חאַראַקטער זאָגט שלמה המלך אַז ועשיר יענה עזותאָ<sup data-n=\"8147\">10</sup>, אָבער די עשירות מיט דער העזה בעדאַרף שטימען, פאַראַן אַזעלכע וואָס די העזה איז מעהר ווי די עשירות<sup data-n=\"8148\">11</sup>.\n<b>הצלת בנ\"י מהפוגרומים</b>\nאין יאָר תר\"מ-תרמ\"א ווען עס זיינען פאָרגעקומען די פאָגראָמען אויף אידן אין רוסלאַנד האָט הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש געזאָגט: ווען מען וואָלט מיר געפאָלגט וואָלט מען אַ סך אידישע בלוט פאַרשפּאָרט.\n<b>הוד</b> כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש האָט אַמאָל געזאָגט צו הוד כ\"ק אאמו\"ר הרה\"ק: איך האָב זיי — צו די פאָרשטייער פון די רוסישע ממשלה — געוואָלט זאָגן אַז אויב ניט, ד. ה. אויב זיי וועלן ניט פאַרבעסערן זייער באַציאונג צו די אידן, פאָר איך אַוועק אין ארץ ישראל און נעם מיט הונדערט טויזנט אידישע פאַמיליעס און איך וואָלט דאָס דורכגעפירט, נאָר דאַמאָלסט איז געווען ענין ”בילו\" און איך האָב ניט געוואָלט מוסיף תוקף זיין, און הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש האָט מסיים געווען: ווען ביי זיי וואָלט געווען דער ”באור ה'\"<sup data-n=\"8149\">12</sup> וואָלט איך אויך געפאָרן<sup data-n=\"8150\">13</sup>.\n<b>אודות הרה\"ח ר' יקותיאל ליעפלער</b>\nהוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש האָט געזאָגט בסעודת חגה\"ש תרמ\"א: פאַר אַן אמת באַצאָלט מען טייער. ווי עס איז ידוע די מעשה פון החסיד ר' יקותיאל ליעפּליער<sup data-n=\"8151\">14</sup>, וואָס איז געווען פריער אַ איש פּשוט. הערענדיג אַמאל אַ תורה פון הוד כ\"ק רבינו הזקן וועגן חלל הימני און חלל השמאלי, איז ער אַרויפגעקראָכן צום פענסטער פון אויבערשטיבל וואו הוד כ\"ק רבנו הזקן האָט זיך געפונען און אַ געשריי געטאָן: רבי, האַקט מיר אָפּ דעם לינקן זייט, איך קען זיך מיט אים ניט ”איספּראַווען\" — אַן עצה געבן.\n<b>האָט</b> אים הוד כ\"ק רבנו הזקן געענטפערט: ואתה מחי' את כולם<sup data-n=\"8152\">15</sup> כתיב, איז מיט די ווערטער האָט אים הוד כ\"ק רבנו הזקן אַריינגעשיינט ראיית אלקות, אַזוי ווי ראי' גשמיות. נאָכדעם, אַז החסיד ר' יקותיאל פלעגט גיין אין גאַס פלעגט אים",[["8147","10","משלי יח, כג."],["8148","11","ספר השיחות תרצ\"ו ע' 31-30."],["8149","12","חברי ”בילו\" קראו א\"ע כן בר\"ת מהפסוק (ישעי' ב, ה) ”בית יעקב לכו ונלכה\"."],["8150","13","ספר השיחות תש\"ה ע' 33-32. ספר התולדות שם ע' 78. ראה גם לקמן ע' תקצג."],["8151","14","אודותו ספה\"ש תש\"ז ע' 84 ובהערות שם [ושם נדפס: אג\"ק . . ח\"ב ע' קיב. וצ\"ל: ח\"ג. וראה גם ח\"ב ע' שטו]. אגרות קודש מאת כ\"ק אדמו\"ר מהוריי\"צ חלק יא ע' כח. היום יום ח חשון. א כסלו. כפר חב\"ד גליון 1085 ע' 18."],["8152","15","נחמי' ט, ו."]]],[2001910681,"אַמאָל אַרינשיינען, פלעגט ער גיין אַ טענצל און האָט דערביי געזאָגט אויף זיך אין רוסיש: חסיד פּרישאָל — דער חסיד איז געקומען — החסיד רש\"ד באַריסאָווער<sup data-n=\"8153\">16</sup> האָט דערציילט, אַז אַמאָל איז ר' יקותיאל ליעפּליער געקומען אין באָריסאָוו און איז אַריינגעגאַנגען אין פּאָסט צו ערליידיגן עפּעס, אינדעם האָט אים אַריינגעשיינט, איז ער געגאַנגען אַ ריקוד מיט'ן פּאָסט<sup data-n=\"8154\">17</sup> באַאַמטען<sup data-n=\"8155\">18</sup>.\n<b>אג\"ק מתרמ\"א — סדר לימוד</b>\n[תרמ\"א-תרמ\"ב]\nבדבר<sup data-n=\"8156\">19</sup> המש'אָ<sup data-n=\"8157\">20</sup> שלו אין לו מה לפחד כלל, והרי שמע בעצמו מכ\"ק אאמו\"ר",[["8153","16","אודותו אגרות קודש מאת כ\"ק אדמו\"ר מהוריי\"צ חלק טז ע' קכח ואילך. מאמרי אדמו\"ר האמצעי קונטרסים ע' תקכו הערה 13. סה\"מ תר\"ם ח\"ב ע' תתקסב. וש\"נ. כפר חב\"ד גליון 1166 ע' 47. באהל רח\"ל ח\"ג ע' 563-567 נדפסה צאוותו (ופאקסימיליא מכתב ידו), ושם ע' 565 כותב תאריך הצוואה ”אור ליום ב, בעשתי עשר חודש בשמיני בו שנת הוא ישוב ירחמנו\" (-תרמ\"ד). ובע' 564 כותב ”שבער\"ה הבע\"ל אהי' בן נ\"ח שנה מיום הולדי\"."],["8154","17","ראה ג\"כ לקוטי דיבורים כרך א כו, ב ואילך. ספר התולדות שם ע' 70."],["8155","18","ספר השיחות תש\"ד ע' 9."],["8156","19","נדפסה בהקדמת אשל אברהם (רא\"י ניימרק, ת\"א תרצ\"ז). כוחה של סניגוריה (פ. שניאורסון, ת\"א תשכ\"ז) ע' 17. אג\"ק קונ' המילואים אגרת יט. והוגהה ע\"פ כתי\"ק שבאוסף המכתבים.\nבספרים הנ\"ל מסופר שנשלחה אל הגה\"ח ר' משולם זלמן ניימרק, בעת מאסרו בסטרדוב בשנים תרמ\"א-ג (כנזכר בהערה לאגרת הקודמת סט\"ו ע' כב) ומסופר שם בארוכה פרטי המעשה.\nבאוסף המכתבים יש כמה אגרות שנכתבו (אל רבינו) מאחד העוסקים למענם בסטרדוב, ממוצש\"ק שמות ומהראשון לינואר (י\"ד שבט) המצפה לישועה (תרמ\"א). ובהן מסופר על המלשינות והמאסר:\nא) סיפר שכך התחלת הדאנס [המלשינות של המשכיל דוב לזרוב], נמצא בפה סטר\"ד [סטרדוב] סעקט נק' חסידים, בהסעקט הזה עד ארבעים איש בראשם הרמ\"ז [ה\"ר משולם זלמן ניימרק], מחזיקים הסעקט דפה הם יאקובסאהן ובעלא דובראווסקי הוא (הלאסנא בדומע דפה) ויעקב משה מענדלייאו וגרשון בן ציון גינזבורג, ובראשם כו' וכו' וכו' [ע\"פ המסופר שם הכוונה לרבינו] וכל עסקם ועצתם להבריח כו' [צעירים מעבודת הצבא] וכל המעות הנמצאים בקאראבעסנע איזבאר הם מקבלים לידם עבור ליתן שוחד, ונשבעים שבועת שקר למען מלט נפשות אשר הם חפצים, ועושים זאת בהיתר כו' וכו' כי ע\"פ עצתו עושים הכל . . בקושי גדול פעלנו ע\"י בקשת האיספראווניק [ראש המשטרה] לעשות להרמ\"ז כדת לא לשנות בגדיו, וליתן לו חדר טוב ולהניח עוד הצטרכותיו . . היום נתראו פנים עם הרמ\"ז בבית הסוהר. .\nב) השבוים יושבים תפוסים בשמירה גדולה, כן הרמ\"ז יחי', וכמעט אין איש מתעסק, כי על כולם נפל אימה מפני חמת המציק הצר הצורר אשר בלשונו מגביר שעוד ידו נטוי' להושיב הבית הסוהר כולו באנשי סטר\"ד נקובים בשם חסידים, ובדברו בשווקים ורחובות . . . כי אני אעשה כלה מכל העיר . . הרמ\"ז זועק ונאנח בשברון מתנים ובחלישות לב, והדאקטער מרשיע לא ליתן לו סויידעטעלשטווע [עדות] לקבלו על ערבות . . כבר הי' זאסידאנייע [ישיבה] בדבר הפראשעני [הבקשה] . . לבקש את השבוים על הערבות ונכתבה ע\"י אדוויקאט [עו\"ד] מפורסם עכ\"ז לא נתקבלה און זיי האבין אפגיזאגט . .\nנראה שרבנו שלח לשם את מזכירו מוה\"ר לוי יצחק אידלעויץ לברר המצב, ובאור ג' יתרו מדווח: יום אתמול נסע הדו\"ח [הדורש וחוקר] מפה על עשרים יום, אמר שנסיעתו יהי' לנאה\"ס לדרוש גין האנשים החתומים על עסק נאימארק ומשם יסע לערי המערב ראהטשאוו הארקי ליובאוויץ . . ובדבר הרמ\"ז אין שום חדש הוא יושב ואחיו לע\"ע בורח. מלשינות נתוספים אנשים נקראים ועוסקים אין, פרוטה אינו נמצאת . . ד' ירחם.\nוכך ישבו שתי שנים, עד למשפט שהתקיים בחורף תרמ\"ג, שבו זוכו הרב ניימרק ושאר החסידים. ובמשך ישיבתו שלח אליו רבינו את האגרת שלפנינו. שמתוכנה נראה שנכתבה בשעה שכבר היה נודע, שלא יתנו לו חופשה עד למשפט, שיתקיים כעבור זמן רב, ולכן מורה לו מה ”שילמוד כל השנה\" בבית הסוהר."],["8157","20","המשפט."]]],[2001910682,"זצלל\"ה זיע\"א<sup data-n=\"8158\">21</sup>, ונכון שילמוד כל השנה משניות מס' ברכות, וגמ' מס' ברכות, והשי\"ת יברכו בכט\"ס כאות נפשו<sup data-n=\"8159\">22</sup>.\n<b>רצונו לעלות לא\"י</b>\nאשר כבוד קדשו מרן אדמו\"ר ר' שמואל מליבאוויץ נ\"ע וזי\"ע ספר לי בפעם האחרונה שראיתי אותו בשנת תרמ\"א, שהוא בעצמו רצה לקנות בית ונחלה בארץ הקדושה דוקא ורצה לקבוע דירתו שמה<sup data-n=\"8160\">23</sup> באופן שתספיק לו נחלתו לפרנסת בני ביתו, והשתדל בזה הרבה רק שע\"י סבה לא נתמלאה בקשתו אז . . היום יום ג' לסדר אל הארץ אשר אראך, שנת ”יקבץ גליות\" [תרנ\"א] לפ\"ק. פה ק\"ק קאטרינאסלוו (יקאטערינאסלאוו) נאום דוב<sup data-n=\"8161\">24</sup> זאב ב\"ר יוסף ז\"ל קאזעווניקאוו<sup data-n=\"8162\">25</sup> חופ\"ק הנ\"ל. (שיבת ציון ווארשא תרנ\"ב ע' 95).",[["8158","21","אדמו\"ר ה”צמח צדק\"."],["8159","22","אגרות קודש מאת כ\"ק אדמו\"ר מהר\"ש ע' כג-כד."],["8160","23","ראה גם לעיל ע' תקצא."],["8161","24","במהדורת ווארשא תר\"ס דוד והוא טעות הדפוס."],["8162","25","הרה\"ג והרה\"ח ר' דוב זאב ב\"ר יוסף קאזעווניקאוו נולד תקצ\"ח או תר\"א בישוב קטן אצל דאבריאנקא [ע\"פ אג\"ק וסה\"ש דבסמוך]. בא אל כ\"ק אדמו\"ר הצ\"צ כשהי' בן י\"ז שנה [ספר השיחות קיץ ה'ש\"ת ע' 32] ושלחו אל ר' הלל בתור יושב ”בשנת תרי\"ח או תרט\"ו\" [אגרות קודש מאת כ\"ק אדמו\"ר מהוריי\"צ ח\"ד ע' נא]. מתלמידי ר\"ה ומחסידי כ\"ק אדמו\"ר הצ\"צ־ מהר\"ש־ מהורש\"ב. בתחילה הי' שד\"ר ואח\"כ רב ביעקאטרינאסלאוו. נסתלק כ\"ז טבת תרס\"ח.\nראה עליו ספר השיחות — תורת שלום ע' 230 (ושם: שאדמו\"ר מהר\"ש בחנו). תרצ\"ז ע' 231 ואילך [ושם: תרנ\"ט הי' בנאות דשא אצל כ\"ק אדמו\"ר מהורש\"ב]. קיץ ה'ש\"ת ע' 32 ואילך [ושם אודות דיבורו]. תש\"א ס\"ע 53-54 [ובהנחה אחרת: שדיבר 4-5 שעות]. רשימות הרב\"ש — תרע\"א (ע' קיח). כרם חב\"ד ג ע' 54-56 [ושם: שבא כסלו תרס\"ב־ תמונתו]. ע' 62 [מכתבו בארמית]. תולדות לוי יצחק ע' 135 ואילך (במהדורת תשנ\"ה).\nנזכר באגרות קודש מאת כ\"ק אדמו\"ר מהורש\"ב ח\"ג ס\"ע רצא־ ס\"ע שמב־ ע' שמז [ושם: ”הרדב\"ז\" — ובהערות המו\"ל: ה\"ר דובער זאב וואלף קוז'ווניקוב]. ח\"ד ס\"ע רמז [ושם: אחרי תוגת נפשי . . אהובינו וידידינו האמיתי הרדב\"ז . . האי מרגניתא טבא שנאבדה מאתנו]. ע' רמח. אג\"ק מהוריי\"צ ח\"ג ע' שכט [ושם: הרה\"ג החסיד . . ספר לי]. ע שפח [ושם: שבא לר\"ה תר\"ן]. ע' תט [ושם: שבא לחגה\"ש תרנ\"ב]. ח\"ד ע' נב. ע' רסה. אג\"ק מאת כ\"ק אדמו\"ר זי\"ע חי\"ד ע' מט [ושם: ”הרה\"ח זאב דוב קאזעווניקאוו\" ובמפתח אנשים שם ע' תקט: קוזבניקוב, זאב דוב]. קונט' ומעין מבית ד' ע' 15. לקו\"ד ח\"א ע' 48. ע' לב ואילך. ע' קה. ח\"ג ע' 856. ס\"ע תמט-898. ח\"ד ע' 1504. ספר השיחות תרצ\"ט ע' 349. תש\"ד ע' 83. ע' 95. תש\"ח ע' 174. תו\"מ רשימת היומן ע' קטו. ע' קיט. התמים חוב' ו ע' צז [שטז]. מגדל עז ע' רמב בערכו. המשפיע ע' קכא. ע' קלד. יומן הר\"א ויינגרטן מהתועדויות חסידים תש\"ז."]]]]});
